const HISTORICAL_EVENTS = [

// ══════════════════════════════════════
// PREHISTORIC & EARLY CIVILISATION
// ══════════════════════════════════════
{ id:1, title:"Invention of Writing (Cuneiform)", year:-3200, lat:31.886, lng:45.2, category:"science", impact:"HIGH", description:"The Sumerians of Mesopotamia developed cuneiform script on clay tablets, the world's first writing system, enabling record-keeping, trade, and the transmission of knowledge across generations.", region:"Middle East", tags:["mesopotamia","writing","sumer"] },
{ id:2, title:"Unification of Upper and Lower Egypt", year:-3100, lat:30.06, lng:31.25, category:"politics", impact:"HIGH", description:"Pharaoh Narmer unified Upper and Lower Egypt, establishing the first dynasty and the foundations of one of history's greatest civilisations, which would endure for over 3,000 years.", region:"Africa", tags:["egypt","unification","pharaoh","narmer"] },
{ id:3, title:"Construction of Stonehenge Begins", year:-3000, lat:51.18, lng:-1.83, category:"culture", impact:"MEDIUM", description:"Construction of the ceremonial monument at Stonehenge in England begins. The iconic standing stones were erected in phases over centuries, aligned with astronomical events such as the solstice sunrise.", region:"Europe", tags:["stonehenge","britain","prehistoric","astronomy"] },
{ id:4, title:"Great Pyramid of Giza Constructed", year:-2560, lat:29.979, lng:31.134, category:"culture", impact:"HIGH", description:"Pharaoh Khufu commissioned the Great Pyramid, which stood as the tallest man-made structure for 3,800 years. Around 20,000 workers laboured for two decades to complete the 146-metre monument.", region:"Africa", tags:["egypt","pyramid","architecture","khufu"] },
{ id:5, title:"Code of Ur-Nammu — Earliest Law Code", year:-2100, lat:30.96, lng:46.1, category:"politics", impact:"HIGH", description:"The oldest surviving law code was written in Sumer under King Ur-Nammu, establishing fines for bodily harm, protections for widows and orphans, and rules governing trade — predating Hammurabi by 300 years.", region:"Middle East", tags:["law","sumer","mesopotamia","ur-nammu"] },
{ id:6, title:"Bronze Age Begins in Europe", year:-2000, lat:45.0, lng:15.0, category:"science", impact:"HIGH", description:"Bronze tools and weapons spread across Europe, transforming agriculture, warfare, and trade. The new alloy technology enabled more sophisticated construction and longer-range trade networks.", region:"Europe", tags:["bronze age","technology","prehistoric","europe"] },
{ id:7, title:"Code of Hammurabi", year:-1754, lat:32.54, lng:44.42, category:"politics", impact:"HIGH", description:"Babylonian King Hammurabi established one of the earliest comprehensive legal codes, with 282 laws carved into a stone stele, establishing proportional punishment and protections for the weak.", region:"Middle East", tags:["law","babylon","hammurabi","justice"] },
{ id:8, title:"Eruption of Thera — Minoan Catastrophe", year:-1628, lat:36.4, lng:25.4, category:"disaster", impact:"HIGH", description:"One of the largest volcanic eruptions in recorded history devastated the Minoan civilisation and may have inspired the legend of Atlantis. It sent ash across the Mediterranean and caused years of climate disruption.", region:"Europe", tags:["volcano","minoan","eruption","santorini"] },
{ id:9, title:"Battle of Kadesh", year:-1274, lat:34.57, lng:36.51, category:"war", impact:"HIGH", description:"The earliest recorded battle in history between Egypt under Ramesses II and the Hittites resulted in history's first recorded peace treaty. Both sides claimed victory in what was one of the largest chariot battles ever fought.", region:"Middle East", tags:["egypt","hittite","ramesses","kadesh"] },
{ id:10, title:"Collapse of Bronze Age Civilisations", year:-1200, lat:37.0, lng:25.0, category:"disaster", impact:"HIGH", description:"Around 1200 BCE a cascade of collapses destroyed most major Bronze Age civilisations including Mycenaean Greece, the Hittites, Ugarit, and the Egyptian New Kingdom. The causes remain debated by historians.", region:"Middle East", tags:["bronze age","collapse","civilisation","catastrophe"] },
{ id:11, title:"First Olympic Games in Greece", year:-776, lat:37.63, lng:21.63, category:"culture", impact:"HIGH", description:"The first recorded Olympic Games were held at Olympia in honour of Zeus, establishing the pan-Hellenic festival that ran for over a millennium and inspired the modern Olympic movement 2,500 years later.", region:"Europe", tags:["olympics","greece","sports","zeus"] },
{ id:12, title:"Founding of Rome", year:-753, lat:41.90, lng:12.50, category:"politics", impact:"HIGH", description:"According to Roman tradition, Romulus founded Rome on the Palatine Hill. The city would grow from a collection of Latin villages to dominate an empire stretching from Britain to Mesopotamia.", region:"Europe", tags:["rome","romulus","foundation","italy"] },
{ id:13, title:"Birth of Confucius", year:-551, lat:35.6, lng:117.05, category:"culture", impact:"HIGH", description:"Confucius was born in the state of Lu in China. His philosophical teachings on ethics, family, loyalty, and governance became the cornerstone of East Asian civilisation, influencing billions across millennia.", region:"Asia", tags:["confucius","philosophy","china","ethics"] },
{ id:14, title:"Birth of Siddhartha Gautama — The Buddha", year:-563, lat:27.48, lng:83.28, category:"religion", impact:"HIGH", description:"Siddhartha Gautama was born in Lumbini, modern Nepal. He attained enlightenment under the Bodhi tree and founded Buddhism, now one of the world's major religions with over 500 million followers.", region:"Asia", tags:["buddha","buddhism","religion","india"] },
{ id:15, title:"Persian Achaemenid Empire Founded", year:-550, lat:30.0, lng:53.0, category:"politics", impact:"HIGH", description:"Cyrus the Great unified the Medes and Persians to found the largest empire the world had yet seen, stretching from the Mediterranean to India, establishing principles of tolerance toward conquered peoples.", region:"Middle East", tags:["persia","cyrus","achaemenid","empire"] },
{ id:16, title:"Democracy Born in Athens", year:-508, lat:37.97, lng:23.73, category:"politics", impact:"HIGH", description:"Cleisthenes introduced democratic reforms in Athens, giving citizens direct participation in governance through the assembly. Athenian democracy became the model for representative government worldwide.", region:"Europe", tags:["athens","democracy","cleisthenes","greece"] },
{ id:17, title:"Battle of Marathon", year:-490, lat:38.14, lng:24.0, category:"war", impact:"HIGH", description:"An outnumbered Athenian force defeated the Persian army of Darius I, halting the first Persian invasion of Greece. The messenger Pheidippides allegedly ran 40km to Athens — the origin of the marathon race.", region:"Europe", tags:["marathon","persia","athens","battle"] },
{ id:18, title:"Battle of Thermopylae", year:-480, lat:38.8, lng:22.53, category:"war", impact:"HIGH", description:"Three hundred Spartan warriors under King Leonidas held the narrow pass of Thermopylae for three days against the massive Persian army of Xerxes I, buying time for Greece to organise its defence.", region:"Europe", tags:["sparta","leonidas","persia","thermopylae"] },
{ id:19, title:"Construction of the Parthenon", year:-447, lat:37.97, lng:23.73, category:"culture", impact:"HIGH", description:"The Parthenon was built on the Acropolis of Athens under Pericles' patronage, becoming the crowning achievement of classical Greek architecture and an enduring symbol of Western civilisation.", region:"Europe", tags:["parthenon","athens","architecture","greece"] },
{ id:20, title:"Plague of Athens", year:-430, lat:37.97, lng:23.73, category:"pandemic", impact:"HIGH", description:"A devastating epidemic, possibly typhoid fever, killed perhaps 25% of Athens's population during the Peloponnesian War, including the great statesman Pericles. Thucydides gave the first clinical description of a plague in history.", region:"Europe", tags:["plague","athens","epidemic","disease"] },
{ id:21, title:"Alexander the Great Conquers Persia", year:-334, lat:37.39, lng:46.73, category:"war", impact:"HIGH", description:"Alexander III of Macedon launched his campaign against the Achaemenid Persian Empire, rapidly conquering territories from Greece to Egypt and India and spreading Greek culture across Asia.", region:"Middle East", tags:["alexander","persia","conquest","hellenism"] },
{ id:22, title:"Qin Shi Huang Unifies China", year:-221, lat:34.35, lng:108.93, category:"politics", impact:"HIGH", description:"The King of Qin conquered all rival states and became the First Emperor of China, standardising weights, measures, writing, and currency, and beginning construction of the Great Wall.", region:"Asia", tags:["china","qin","unification","great wall"] },
{ id:23, title:"Assassination of Julius Caesar", year:-44, lat:41.9, lng:12.48, category:"politics", impact:"HIGH", description:"Julius Caesar was stabbed 23 times by senators led by Brutus and Cassius on the Ides of March. His death triggered a civil war and ultimately ended the Roman Republic, leading to the Roman Empire.", region:"Europe", tags:["caesar","rome","assassination","republic"] },
{ id:24, title:"Birth of Jesus Christ", year:1, lat:31.71, lng:35.2, category:"religion", impact:"HIGH", description:"The birth of Jesus of Nazareth in Bethlehem, whose teachings and life formed the foundation of Christianity, now the world's largest religion with over 2.4 billion adherents — roughly one-third of humanity.", region:"Middle East", tags:["jesus","christianity","religion","bethlehem"] },

// ══════════════════════════════════════
// ROMAN EMPIRE & CLASSICAL
// ══════════════════════════════════════
{ id:25, title:"Eruption of Mount Vesuvius — Pompeii Buried", year:79, lat:40.82, lng:14.43, category:"disaster", impact:"HIGH", description:"Mount Vesuvius erupted catastrophically, burying the Roman cities of Pompeii and Herculaneum under metres of ash and pumice, preserving them as a unique archaeological time capsule of first-century Roman life.", region:"Europe", tags:["vesuvius","pompeii","volcano","rome"] },
{ id:26, title:"Colosseum Completed in Rome", year:80, lat:41.89, lng:12.49, category:"culture", impact:"MEDIUM", description:"The Flavian Amphitheatre was completed in Rome, capable of seating 50,000–80,000 spectators for gladiatorial contests and public spectacles. It remains the largest amphitheatre ever built.", region:"Europe", tags:["colosseum","rome","architecture","gladiators"] },
{ id:27, title:"Edict of Milan — Christianity Legalised", year:313, lat:45.46, lng:9.19, category:"religion", impact:"HIGH", description:"Emperor Constantine issued the Edict of Milan, granting religious tolerance and ending the persecution of Christians. Christianity soon became the Roman Empire's official religion, transforming Western civilisation.", region:"Europe", tags:["constantine","christianity","edict","rome"] },
{ id:28, title:"Fall of the Western Roman Empire", year:476, lat:41.9, lng:12.49, category:"politics", impact:"HIGH", description:"Romulus Augustulus, the last Western Roman Emperor, was deposed by the Germanic chieftain Odoacer. This date marks the end of antiquity and the beginning of the Middle Ages in Western Europe.", region:"Europe", tags:["rome","fall","medieval","empire"] },
{ id:29, title:"Plague of Justinian — First Bubonic Plague", year:541, lat:41.01, lng:28.97, category:"pandemic", impact:"HIGH", description:"The first confirmed outbreak of bubonic plague swept the Byzantine Empire and Mediterranean world, killing perhaps 25 million people — roughly half the population of the affected regions.", region:"Europe", tags:["plague","justinian","pandemic","byzantine"] },

// ══════════════════════════════════════
// EARLY MEDIEVAL
// ══════════════════════════════════════
{ id:30, title:"Birth of Muhammad — Founder of Islam", year:570, lat:21.42, lng:39.83, category:"religion", impact:"HIGH", description:"Muhammad ibn Abdullah was born in Mecca. His revelations founded Islam, which spread from Spain to Indonesia and today has 1.9 billion followers — the world's second-largest religion.", region:"Middle East", tags:["muhammad","islam","religion","mecca"] },
{ id:31, title:"Hijra — Muhammad Migrates to Medina", year:622, lat:24.47, lng:39.61, category:"religion", impact:"HIGH", description:"Muhammad's migration from Mecca to Medina marks Year 1 of the Islamic calendar and the founding of the first Muslim community, transforming a religious movement into a political and social force.", region:"Middle East", tags:["hijra","muhammad","islam","medina"] },
{ id:32, title:"Arab Conquest of Persia", year:636, lat:32.0, lng:47.0, category:"war", impact:"HIGH", description:"Arab Muslim forces defeated the Sassanid Persian Empire, ending 400 years of Zoroastrian Persian rule and beginning the Islamisation of Iran, permanently reshaping the culture and religion of the entire region.", region:"Middle East", tags:["arab","persia","islam","conquest"] },
{ id:33, title:"Battle of Tours — Arab Expansion Halted", year:732, lat:47.39, lng:0.68, category:"war", impact:"HIGH", description:"Charles Martel defeated the Umayyad Caliphate's northward expansion into France near Tours. Historians consider it among the most decisive battles in Western history, preserving Christian Europe.", region:"Europe", tags:["tours","charles martel","frankish","arab"] },
{ id:34, title:"Charlemagne Crowned Holy Roman Emperor", year:800, lat:41.9, lng:12.45, category:"politics", impact:"HIGH", description:"Pope Leo III crowned Charlemagne on Christmas Day, creating the Holy Roman Empire and establishing the political-religious alliance that shaped medieval European governance for centuries.", region:"Europe", tags:["charlemagne","holy roman empire","pope","carolingian"] },
{ id:35, title:"Viking Raids Begin — Lindisfarne", year:793, lat:55.68, lng:-1.8, category:"war", impact:"HIGH", description:"The raid on the monastery of Lindisfarne marks the traditional beginning of the Viking Age. Norse warriors would terrorise and eventually settle coastal and river regions across Europe for 250 years.", region:"Europe", tags:["vikings","norse","lindisfarne","raid"] },
{ id:36, title:"Woodblock Printing Invented in China", year:868, lat:39.9, lng:116.4, category:"science", impact:"HIGH", description:"The Diamond Sutra, printed in China using woodblock printing, is the world's oldest surviving dated printed book, predating Gutenberg's movable type by nearly 600 years.", region:"Asia", tags:["printing","china","buddhism","book"] },
{ id:37, title:"Battle of Hastings — Norman Conquest", year:1066, lat:50.91, lng:0.49, category:"war", impact:"HIGH", description:"William the Conqueror defeated King Harold II of England, fundamentally transforming English culture, language, and governance through the introduction of Norman French feudalism.", region:"Europe", tags:["hastings","william","normans","conquest"] },
{ id:38, title:"First Crusade — Jerusalem Captured", year:1095, lat:31.77, lng:35.23, category:"war", impact:"HIGH", description:"Pope Urban II launched the First Crusade, which resulted in the capture of Jerusalem in 1099 and established the Crusader states, reshaping Middle Eastern and European history for two centuries.", region:"Middle East", tags:["crusade","pope urban","jerusalem","religion"] },
{ id:39, title:"Magna Carta Signed", year:1215, lat:51.44, lng:-0.57, category:"politics", impact:"HIGH", description:"King John of England was forced to sign the Magna Carta at Runnymede, establishing that the king was subject to the rule of law — the foundational document of constitutional government and individual rights.", region:"Europe", tags:["magna carta","john","england","law"] },
{ id:40, title:"Genghis Khan Unifies Mongol Tribes", year:1206, lat:47.89, lng:106.91, category:"politics", impact:"HIGH", description:"Temüjin united the Mongolian tribes and was proclaimed Genghis Khan. He created the largest contiguous land empire in history, reshaping the demographic and cultural map of Eurasia.", region:"Asia", tags:["genghis khan","mongols","empire","asia"] },
{ id:41, title:"Mongol Sack of Baghdad — End of Islamic Golden Age", year:1258, lat:33.34, lng:44.4, category:"war", impact:"HIGH", description:"Hulagu Khan's army destroyed Baghdad, killing an estimated 200,000–800,000 people and obliterating the Abbasid Caliphate. The House of Wisdom was burned, marking the end of the Islamic Golden Age.", region:"Middle East", tags:["mongols","baghdad","abbasid","destruction"] },
{ id:42, title:"Black Death Arrives in Europe", year:1347, lat:37.5, lng:15.09, category:"pandemic", impact:"HIGH", description:"The bubonic plague arrived in Sicily from the Black Sea. Within five years it killed 30–60% of Europe's population — approximately 25 million people — in history's deadliest pandemic.", region:"Europe", tags:["black death","plague","pandemic","europe"] },
{ id:43, title:"Hundred Years War Begins", year:1337, lat:48.85, lng:2.35, category:"war", impact:"HIGH", description:"The series of conflicts between England and France over the French throne lasted 116 years, reshaping national identities on both sides and producing heroes like Edward the Black Prince and Joan of Arc.", region:"Europe", tags:["hundred years war","england","france","medieval"] },
{ id:44, title:"Joan of Arc Relieves Siege of Orléans", year:1429, lat:47.9, lng:1.9, category:"war", impact:"HIGH", description:"The teenage peasant girl Joan of Arc led French troops to break the English siege of Orléans, reinvigorating France's war effort. She was later captured and burned as a heretic, then canonised as a saint.", region:"Europe", tags:["joan of arc","france","orleans","hundred years war"] },
{ id:45, title:"Gutenberg Invents the Printing Press", year:1440, lat:49.99, lng:8.25, category:"science", impact:"HIGH", description:"Johannes Gutenberg's movable-type printing press revolutionised book production, enabling mass literacy and the rapid spread of ideas — the critical technology enabling the Renaissance, Reformation, and Scientific Revolution.", region:"Europe", tags:["gutenberg","printing press","knowledge","revolution"] },
{ id:46, title:"Fall of Constantinople to the Ottomans", year:1453, lat:41.01, lng:28.98, category:"war", impact:"HIGH", description:"Ottoman Sultan Mehmed II captured Constantinople with cannon bombardment, ending the Byzantine Empire after 1,100 years. Greek scholars fled westward, helping spark the Italian Renaissance.", region:"Middle East", tags:["constantinople","ottoman","byzantine","mehmed"] },

// ══════════════════════════════════════
// AGE OF EXPLORATION
// ══════════════════════════════════════
{ id:47, title:"Columbus Reaches the Americas", year:1492, lat:24.05, lng:-74.53, category:"exploration", impact:"HIGH", description:"Christopher Columbus made landfall in the Bahamas on October 12, initiating sustained contact between Europe and the Americas and transforming both hemispheres through the Columbian Exchange.", region:"Americas", tags:["columbus","discovery","americas","spain"] },
{ id:48, title:"Vasco da Gama Reaches India by Sea", year:1498, lat:11.26, lng:75.78, category:"exploration", impact:"HIGH", description:"Vasco da Gama's fleet became the first to sail directly from Europe to India around the Cape of Good Hope, ending Arab and Venetian control over the spice trade and launching Portuguese maritime empire.", region:"Asia", tags:["vasco da gama","india","portugal","spice route"] },
{ id:49, title:"Spanish Conquest of Mexico — Aztec Empire Falls", year:1519, lat:19.43, lng:-99.13, category:"war", impact:"HIGH", description:"Hernán Cortés arrived in Mexico and, through military skill, indigenous alliances, and devastating smallpox outbreaks, conquered the Aztec Empire within two years, claiming it for Spain.", region:"Americas", tags:["cortes","aztec","conquest","mexico"] },
{ id:50, title:"Martin Luther's 95 Theses — Protestant Reformation", year:1517, lat:51.87, lng:12.64, category:"religion", impact:"HIGH", description:"Martin Luther published his 95 Theses challenging the Catholic Church's sale of indulgences, triggering the Protestant Reformation that permanently fractured Western Christianity.", region:"Europe", tags:["luther","reformation","protestant","church"] },
{ id:51, title:"Magellan-Elcano First Circumnavigation", year:1522, lat:37.39, lng:-5.98, category:"exploration", impact:"HIGH", description:"Ferdinand Magellan's expedition, completed by Juan Sebastián Elcano after Magellan's death in the Philippines, became the first to circumnavigate the globe, definitively proving Earth's spherical shape.", region:"Europe", tags:["magellan","circumnavigation","exploration","globe"] },
{ id:52, title:"Copernicus Publishes Heliocentric Theory", year:1543, lat:54.35, lng:18.65, category:"science", impact:"HIGH", description:"Copernicus published his model placing the Sun at the centre of the solar system, launching the Scientific Revolution that eventually overturned centuries of Church-endorsed geocentric cosmology.", region:"Europe", tags:["copernicus","heliocentric","astronomy","science"] },
{ id:53, title:"Defeat of the Spanish Armada", year:1588, lat:50.91, lng:-1.4, category:"war", impact:"HIGH", description:"The English fleet defeated Spain's supposedly invincible Armada, ending plans to invade England and shifting naval supremacy toward England, which would become the world's dominant maritime power.", region:"Europe", tags:["armada","england","spain","naval"] },
{ id:54, title:"Galileo Turns Telescope to the Night Sky", year:1609, lat:45.41, lng:11.88, category:"science", impact:"HIGH", description:"Galileo improved the telescope and discovered Jupiter's four large moons, the phases of Venus, and craters on the Moon, providing strong evidence for the Copernican heliocentric model.", region:"Europe", tags:["galileo","telescope","astronomy","jupiter"] },
{ id:55, title:"Thirty Years War Devastates Europe", year:1618, lat:50.08, lng:14.44, category:"war", impact:"HIGH", description:"The Thirty Years War killed up to one-third of the German population. Ending with the Peace of Westphalia, it established the modern principle of state sovereignty still central to international law today.", region:"Europe", tags:["thirty years war","germany","religion","westphalia"] },
{ id:56, title:"Peace of Westphalia — Modern State System", year:1648, lat:51.96, lng:7.63, category:"politics", impact:"HIGH", description:"The Peace of Westphalia ended the Thirty Years War and established the modern principle of national sovereignty, creating the state-centric international order that governs international relations to this day.", region:"Europe", tags:["westphalia","sovereignty","peace","international law"] },
{ id:57, title:"Isaac Newton Publishes Principia Mathematica", year:1687, lat:52.21, lng:0.12, category:"science", impact:"HIGH", description:"Newton's Principia established the laws of motion and universal gravitation, unifying terrestrial and celestial mechanics. It is arguably the most important scientific work ever written.", region:"Europe", tags:["newton","gravity","physics","principia"] },
{ id:58, title:"Glorious Revolution — Constitutional Monarchy in England", year:1688, lat:51.51, lng:-0.13, category:"politics", impact:"HIGH", description:"William of Orange overthrew King James II, establishing constitutional monarchy and parliamentary supremacy. The resulting Bill of Rights became a model for democratic governance worldwide.", region:"Europe", tags:["glorious revolution","william","parliament","constitution"] },
{ id:59, title:"Great Fire of London", year:1666, lat:51.51, lng:-0.09, category:"disaster", impact:"HIGH", description:"Starting in a bakery on Pudding Lane, the Great Fire burned for four days, destroying 13,200 houses, 87 churches, and most of medieval London. It ended the Great Plague and enabled a modern city to rise.", region:"Europe", tags:["great fire","london","disaster","rebuild"] },
{ id:60, title:"Great Plague of London", year:1665, lat:51.51, lng:-0.13, category:"pandemic", impact:"HIGH", description:"The last major outbreak of bubonic plague in England killed approximately 100,000 people — roughly 15% of London's population — in 18 months, spread through the city's crowded and unsanitary conditions.", region:"Europe", tags:["plague","london","pandemic","disease"] },

// ══════════════════════════════════════
// ENLIGHTENMENT & REVOLUTIONS
// ══════════════════════════════════════
{ id:61, title:"Industrial Revolution Begins in Britain", year:1760, lat:53.48, lng:-2.24, category:"economy", impact:"HIGH", description:"The mechanisation of textile production in Lancashire, powered by the steam engine, marked the beginning of the Industrial Revolution, transforming the entire world from agrarian to industrial economies.", region:"Europe", tags:["industrial revolution","steam engine","cotton","britain"] },
{ id:62, title:"James Watt Improves the Steam Engine", year:1769, lat:55.86, lng:-4.25, category:"science", impact:"HIGH", description:"James Watt patented his improved steam engine with a separate condenser, making it practical enough to power factories, mines, and eventually railways. His engine is the central machine of the Industrial Revolution.", region:"Europe", tags:["steam engine","watt","industrial revolution","scotland"] },
{ id:63, title:"American Declaration of Independence", year:1776, lat:39.95, lng:-75.15, category:"politics", impact:"HIGH", description:"The thirteen American colonies declared independence from Britain in Philadelphia. The Declaration's assertion that 'all men are created equal' became a template for democratic revolutions and independence movements worldwide.", region:"Americas", tags:["independence","usa","revolution","democracy"] },
{ id:64, title:"French Revolution — Storming of the Bastille", year:1789, lat:48.85, lng:2.37, category:"politics", impact:"HIGH", description:"The storming of the Bastille on July 14 launched the French Revolution, overthrowing the monarchy and establishing ideals of liberté, égalité, fraternité that transformed European and global politics for centuries.", region:"Europe", tags:["french revolution","bastille","liberty","republic"] },
{ id:65, title:"Haitian Revolution — First Black Republic", year:1791, lat:19.45, lng:-72.68, category:"war", impact:"HIGH", description:"The enslaved population of Saint-Domingue rose in revolt, launching the only successful slave rebellion in history. In 1804, Haiti became the world's first Black republic and the first nation founded by formerly enslaved people.", region:"Americas", tags:["haiti","revolution","slavery","independence"] },
{ id:66, title:"Napoleon Seizes Power in France", year:1799, lat:48.85, lng:2.35, category:"politics", impact:"HIGH", description:"Napoleon's coup d'état ended the French Directory. Within five years he crowned himself Emperor and conquered most of Europe, redrawing the continent's map and spreading the Napoleonic Code.", region:"Europe", tags:["napoleon","coup","france","empire"] },
{ id:67, title:"Battle of Trafalgar — British Naval Supremacy", year:1805, lat:36.19, lng:-6.01, category:"war", impact:"HIGH", description:"Admiral Nelson's British fleet destroyed the combined French and Spanish navies off Cape Trafalgar, securing British naval supremacy for the next century. Nelson was killed by a French sniper during the battle.", region:"Europe", tags:["trafalgar","nelson","napoleon","naval"] },
{ id:68, title:"Battle of Waterloo — Napoleon Defeated", year:1815, lat:50.68, lng:4.41, category:"war", impact:"HIGH", description:"The Duke of Wellington and Prussian forces decisively defeated Napoleon Bonaparte near Brussels, ending 23 years of near-continuous European conflict. Napoleon was exiled to Saint Helena.", region:"Europe", tags:["waterloo","napoleon","wellington","belgium"] },
{ id:69, title:"Tambora Eruption — Year Without a Summer", year:1815, lat:-8.25, lng:117.99, category:"disaster", impact:"HIGH", description:"The largest volcanic eruption in recorded history caused the 'Year Without a Summer' of 1816. Crop failures caused famines across Europe, North America, and Asia, killing tens of thousands.", region:"Asia", tags:["tambora","volcano","eruption","famine"] },
{ id:70, title:"Abolition of Slavery in British Empire", year:1833, lat:51.5, lng:-0.13, category:"politics", impact:"HIGH", description:"The Slavery Abolition Act freed approximately 800,000 enslaved people across the British Empire. Abolitionists had campaigned for decades; it was a landmark moral achievement of the 19th century.", region:"Europe", tags:["slavery","abolition","britain","wilberforce"] },
{ id:71, title:"Irish Potato Famine", year:1845, lat:53.33, lng:-6.25, category:"disaster", impact:"HIGH", description:"A potato blight destroyed Ireland's primary food crop, killing approximately one million people and causing another million to emigrate within five years. Ireland's population fell by 25% and emigration continued for decades.", region:"Europe", tags:["ireland","famine","potato","emigration"] },
{ id:72, title:"Communist Manifesto Published", year:1848, lat:51.51, lng:-0.13, category:"politics", impact:"HIGH", description:"Karl Marx and Friedrich Engels published the Communist Manifesto calling for workers to seize the means of production. It became the founding document of communist movements that would dominate the 20th century.", region:"Europe", tags:["marx","communism","manifesto","socialism"] },
{ id:73, title:"Darwin Publishes On the Origin of Species", year:1859, lat:51.51, lng:-0.13, category:"science", impact:"HIGH", description:"Darwin's theory of evolution by natural selection revolutionised biology and humanity's understanding of its place in nature. It remains the unifying theory of all life sciences.", region:"Europe", tags:["darwin","evolution","biology","natural selection"] },

// ══════════════════════════════════════
// AMERICAN CIVIL WAR & LATE 19TH CENTURY
// ══════════════════════════════════════
{ id:74, title:"American Civil War Begins at Fort Sumter", year:1861, lat:32.78, lng:-79.93, category:"war", impact:"HIGH", description:"Confederate forces attacked Fort Sumter, beginning four years of civil war over slavery and states' rights. More than 620,000 soldiers died — more American deaths than in all other US wars combined.", region:"Americas", tags:["civil war","usa","slavery","confederacy"] },
{ id:75, title:"Emancipation Proclamation", year:1863, lat:38.9, lng:-77.04, category:"politics", impact:"HIGH", description:"President Lincoln's executive order declared enslaved people in Confederate states to be free, transforming the Civil War into a moral crusade against slavery and changing the legal status of 3.5 million people.", region:"Americas", tags:["emancipation","lincoln","slavery","usa"] },
{ id:76, title:"American Civil War Ends — Lee Surrenders", year:1865, lat:37.36, lng:-78.79, category:"war", impact:"HIGH", description:"General Lee surrendered to Grant at Appomattox, ending the Civil War with Union victory and abolition of slavery. Five days later, Abraham Lincoln was assassinated at Ford's Theatre.", region:"Americas", tags:["civil war","lee","appomattox","lincoln"] },
{ id:77, title:"Meiji Restoration — Japan Modernises", year:1868, lat:35.68, lng:139.69, category:"politics", impact:"HIGH", description:"The Meiji Restoration ended 265 years of Tokugawa rule and launched Japan's rapid industrialisation and Westernisation, transforming it from a feudal state to a world power within 40 years.", region:"Asia", tags:["meiji","japan","modernisation","industrialisation"] },
{ id:78, title:"Suez Canal Opens", year:1869, lat:30.43, lng:32.34, category:"economy", impact:"HIGH", description:"The 193km Suez Canal connecting the Mediterranean to the Red Sea opened, dramatically shortening maritime routes between Europe and Asia and reshaping global trade and colonial strategy.", region:"Africa", tags:["suez canal","egypt","trade","engineering"] },
{ id:79, title:"German Empire Proclaimed at Versailles", year:1871, lat:48.8, lng:2.12, category:"politics", impact:"HIGH", description:"Otto von Bismarck's military victories against Austria and France unified Germany under Prussian leadership. The new German Empire became Europe's strongest industrial and military power.", region:"Europe", tags:["germany","bismarck","unification","prussia"] },
{ id:80, title:"Alexander Graham Bell Invents the Telephone", year:1876, lat:42.36, lng:-71.06, category:"science", impact:"HIGH", description:"Bell successfully transmitted the first intelligible speech over electric wire on March 10, 1876, launching the telecommunications revolution that transformed human communication and commerce.", region:"Americas", tags:["telephone","bell","communication","invention"] },
{ id:81, title:"Thomas Edison Demonstrates the Light Bulb", year:1879, lat:40.69, lng:-74.3, category:"science", impact:"HIGH", description:"Edison demonstrated a practical incandescent light bulb, launching the electrical revolution that would transform cities, factories, and homes worldwide, ending millennia of reliance on fire for artificial light.", region:"Americas", tags:["edison","light bulb","electricity","invention"] },
{ id:82, title:"Krakatoa Eruption — Heard Around the World", year:1883, lat:-6.1, lng:105.42, category:"disaster", impact:"HIGH", description:"The catastrophic eruption of Krakatoa was heard 5,000km away — the loudest sound ever recorded. Tsunamis killed 36,000 people, and the ash cloud caused vivid sunsets globally and lowered world temperatures.", region:"Asia", tags:["krakatoa","volcano","tsunami","indonesia"] },
{ id:83, title:"Berlin Conference — Scramble for Africa", year:1884, lat:52.52, lng:13.41, category:"politics", impact:"HIGH", description:"European powers divided Africa among themselves without African input. Within 20 years, 90% of Africa was under European colonial control. The borders arbitrarily drawn here still cause conflicts today.", region:"Africa", tags:["berlin conference","africa","colonialism","europe"] },
{ id:84, title:"Marie Curie Discovers Radioactivity", year:1898, lat:48.85, lng:2.35, category:"science", impact:"HIGH", description:"Marie Curie discovered the elements polonium and radium and coined the term radioactivity. She became the first woman to win a Nobel Prize and the only person to win in two different sciences.", region:"Europe", tags:["curie","radioactivity","science","nobelprize"] },
{ id:85, title:"Wright Brothers Achieve First Powered Flight", year:1903, lat:36.01, lng:-75.66, category:"science", impact:"HIGH", description:"Orville and Wilbur Wright achieved the first sustained, controlled, powered heavier-than-air flight at Kitty Hawk, inaugurating the aviation age that transformed warfare, commerce, and travel within decades.", region:"Americas", tags:["wright brothers","flight","aviation","kitty hawk"] },
{ id:86, title:"Einstein Publishes Special Relativity — E=mc²", year:1905, lat:47.37, lng:8.54, category:"science", impact:"HIGH", description:"Einstein's special theory of relativity established that the speed of light is constant and yielded the famous equation E=mc², which became the basis for understanding nuclear energy.", region:"Europe", tags:["einstein","relativity","physics","e=mc2"] },
{ id:87, title:"Titanic Sinks in the North Atlantic", year:1912, lat:41.73, lng:-49.95, category:"disaster", impact:"HIGH", description:"The 'unsinkable' RMS Titanic struck an iceberg and sank in the North Atlantic, killing 1,500 of 2,224 passengers and crew. The disaster led to major improvements in maritime safety regulations.", region:"Americas", tags:["titanic","shipwreck","iceberg","atlantic"] },

// ══════════════════════════════════════
// WORLD WAR I
// ══════════════════════════════════════
{ id:88, title:"Assassination of Archduke Franz Ferdinand", year:1914, lat:43.86, lng:18.41, category:"war", impact:"HIGH", description:"Archduke Franz Ferdinand was assassinated in Sarajevo by Gavrilo Princip, triggering the chain of alliances that led to World War I — the conflict that killed 17 million people and destroyed four empires.", region:"Europe", tags:["franz ferdinand","sarajevo","wwi","assassination"] },
{ id:89, title:"World War I — War of the Trenches", year:1914, lat:50.0, lng:4.0, category:"war", impact:"HIGH", description:"The Great War consumed an entire generation across Europe, with industrial-scale slaughter in the trenches of the Western Front. Poison gas, tanks, and aerial warfare made their devastating debut.", region:"Europe", tags:["wwi","world war","trenches","poison gas"] },
{ id:90, title:"Battle of the Somme — Bloodiest Day in British History", year:1916, lat:50.0, lng:2.75, category:"war", impact:"HIGH", description:"On July 1, 1916, the British Army suffered 57,470 casualties in a single day — its worst in military history. The four-month battle produced over 1 million casualties for minimal territorial gain.", region:"Europe", tags:["somme","wwi","britain","casualties"] },
{ id:91, title:"Russian Revolution — Bolsheviks Seize Power", year:1917, lat:59.93, lng:30.32, category:"politics", impact:"HIGH", description:"Lenin's Bolsheviks overthrew the Provisional Government, establishing the world's first communist state. The revolution reshaped global politics for the entire remainder of the 20th century.", region:"Europe", tags:["russian revolution","bolshevik","Lenin","communism"] },
{ id:92, title:"Spanish Flu Pandemic Kills 50 Million", year:1918, lat:40.42, lng:-3.7, category:"pandemic", impact:"HIGH", description:"The 1918 influenza pandemic infected 500 million people worldwide and killed an estimated 50–100 million — more than died in WWI. It struck hardest at healthy young adults aged 20–40.", region:"Global", tags:["spanish flu","pandemic","influenza","wwi"] },
{ id:93, title:"World War I Ends — Armistice Signed", year:1918, lat:49.41, lng:3.08, category:"war", impact:"HIGH", description:"At the 11th hour of the 11th day of the 11th month, the Armistice ended four years of war. Approximately 17 million had been killed and four empires — Ottoman, Russian, German, Austro-Hungarian — destroyed.", region:"Europe", tags:["wwi","armistice","peace","1918"] },
{ id:94, title:"Treaty of Versailles", year:1919, lat:48.8, lng:2.12, category:"politics", impact:"HIGH", description:"The punitive peace treaty imposed massive reparations and territorial losses on Germany. Its severity created the economic desperation that Hitler exploited to rise to power, making WWII effectively inevitable.", region:"Europe", tags:["versailles","wwi","germany","peace treaty"] },
{ id:95, title:"Alexander Fleming Discovers Penicillin", year:1928, lat:51.51, lng:-0.13, category:"science", impact:"HIGH", description:"Fleming noticed that mould Penicillium notatum inhibited bacterial growth, leading to the development of penicillin — the world's first antibiotic and one of the most important medical discoveries in history.", region:"Europe", tags:["penicillin","fleming","antibiotic","medicine"] },
{ id:96, title:"Wall Street Crash — Great Depression", year:1929, lat:40.71, lng:-74.01, category:"economy", impact:"HIGH", description:"The US stock market collapsed catastrophically, triggering the Great Depression — the worst economic downturn in the 20th century, with unemployment reaching 25% in the US and devastating global trade.", region:"Americas", tags:["wall street crash","depression","economy","1929"] },
{ id:97, title:"Hitler Becomes Chancellor of Germany", year:1933, lat:52.52, lng:13.41, category:"politics", impact:"HIGH", description:"Hitler's appointment as Chancellor marked the end of the Weimar Republic. Within months he had seized dictatorial power, setting Germany on the path to war and genocide.", region:"Europe", tags:["hitler","nazi","germany","chancellor"] },

// ══════════════════════════════════════
// WORLD WAR II
// ══════════════════════════════════════
{ id:98, title:"Germany Invades Poland — World War II Begins", year:1939, lat:52.23, lng:21.01, category:"war", impact:"HIGH", description:"Nazi Germany invaded Poland on September 1. Britain and France declared war two days later. World War II would kill 70–85 million people — roughly 3% of the entire 1940 world population.", region:"Europe", tags:["wwii","poland","invasion","germany"] },
{ id:99, title:"Battle of Britain — RAF Defeats Luftwaffe", year:1940, lat:51.51, lng:-0.13, category:"war", impact:"HIGH", description:"The Luftwaffe's air campaign to gain superiority over Britain was defeated by the RAF — Hitler's first major military defeat. Churchill: 'Never was so much owed by so many to so few.'", region:"Europe", tags:["battle of britain","raf","luftwaffe","wwii"] },
{ id:100, title:"Holocaust — The Final Solution", year:1942, lat:52.44, lng:13.16, category:"war", impact:"HIGH", description:"Nazi leaders formalised the 'Final Solution' at the Wannsee Conference — the systematic genocide of Jewish people and minorities. Six million Jews were murdered, along with millions of others.", region:"Europe", tags:["holocaust","wannsee","genocide","nazi"] },
{ id:101, title:"Battle of Stalingrad — Turning Point of WWII", year:1942, lat:48.71, lng:44.52, category:"war", impact:"HIGH", description:"The six-month battle for Stalingrad encircled and destroyed an entire German army, marking the decisive turning point on the Eastern Front and the beginning of the long German retreat to Berlin.", region:"Europe", tags:["stalingrad","wwii","russia","germany"] },
{ id:102, title:"D-Day — Allied Invasion of Normandy", year:1944, lat:49.37, lng:-0.76, category:"war", impact:"HIGH", description:"Operation Overlord landed 156,000 Allied troops on five Normandy beaches on June 6 — the largest seaborne invasion in history. It opened the Western Front and sealed Germany's eventual defeat.", region:"Europe", tags:["d-day","normandy","wwii","invasion"] },
{ id:103, title:"Atomic Bombing of Hiroshima", year:1945, lat:34.39, lng:132.45, category:"war", impact:"HIGH", description:"The United States dropped the 'Little Boy' atomic bomb on Hiroshima on August 6, instantly killing 70,000–80,000 people. Three days later Nagasaki was bombed. Japan surrendered August 15.", region:"Asia", tags:["hiroshima","atomic bomb","wwii","usa"] },
{ id:104, title:"World War II Ends — V-E Day and V-J Day", year:1945, lat:48.85, lng:2.35, category:"war", impact:"HIGH", description:"Germany surrendered on May 8 and Japan on September 2, ending the deadliest conflict in history. An estimated 70–85 million people had been killed. The UN, NATO, and Cold War emerged from this destruction.", region:"Global", tags:["wwii","victory","surrender","peace"] },
{ id:105, title:"United Nations Founded", year:1945, lat:37.77, lng:-122.42, category:"politics", impact:"HIGH", description:"Representatives of 51 nations signed the UN Charter in San Francisco, creating an international organisation to prevent future wars and promote global cooperation, decolonisation, and human rights.", region:"Americas", tags:["united nations","peace","international","san francisco"] },

// ══════════════════════════════════════
// COLD WAR ERA
// ══════════════════════════════════════
{ id:106, title:"Indian Independence from Britain", year:1947, lat:28.61, lng:77.21, category:"politics", impact:"HIGH", description:"India gained independence on August 15, ending nearly 200 years of British rule. Partition into India and Pakistan triggered mass migration of 14 million people and sectarian violence killing up to 2 million.", region:"Asia", tags:["india","independence","gandhi","partition"] },
{ id:107, title:"State of Israel Founded", year:1948, lat:32.09, lng:34.78, category:"politics", impact:"HIGH", description:"David Ben-Gurion proclaimed the State of Israel on May 14. The Arab League immediately launched a war; Israel survived and expanded, creating 700,000 Palestinian refugees and beginning an ongoing conflict.", region:"Middle East", tags:["israel","palestine","independence","1948 war"] },
{ id:108, title:"NATO Founded — Cold War Alliance", year:1949, lat:50.85, lng:4.35, category:"politics", impact:"HIGH", description:"Twelve Western nations signed the North Atlantic Treaty creating NATO as a collective defence alliance against Soviet expansion. The organisation has since expanded to 32 members.", region:"Europe", tags:["nato","cold war","military","alliance"] },
{ id:109, title:"People's Republic of China Founded", year:1949, lat:39.91, lng:116.4, category:"politics", impact:"HIGH", description:"Mao Zedong proclaimed the People's Republic of China after Communist victory in the civil war. China's revolution profoundly shaped global geopolitics throughout the Cold War.", region:"Asia", tags:["china","mao","communist","people's republic"] },
{ id:110, title:"Korean War", year:1950, lat:37.57, lng:126.98, category:"war", impact:"HIGH", description:"North Korea invaded South Korea, drawing in US-led UN forces and Chinese troops. The war killed approximately 5 million people and ended in a 1953 armistice with Korea still divided at the 38th parallel.", region:"Asia", tags:["korea","cold war","usa","china"] },
{ id:111, title:"DNA Double Helix Structure Discovered", year:1953, lat:52.21, lng:0.12, category:"science", impact:"HIGH", description:"Watson and Crick, building on Franklin's X-ray data, described the double-helix structure of DNA, unlocking the molecular basis of heredity and launching the modern era of molecular biology.", region:"Europe", tags:["dna","watson","crick","genetics"] },
{ id:112, title:"Polio Vaccine — Jonas Salk", year:1955, lat:42.36, lng:-83.06, category:"science", impact:"HIGH", description:"Jonas Salk's inactivated polio vaccine was declared safe and effective, effectively eliminating the paralysing disease that had afflicted millions. Albert Sabin's oral vaccine followed in 1961.", region:"Americas", tags:["polio","salk","vaccine","medicine"] },
{ id:113, title:"Sputnik 1 — First Artificial Satellite", year:1957, lat:45.92, lng:63.34, category:"science", impact:"HIGH", description:"The Soviet Union launched Sputnik 1, the first artificial Earth satellite, on October 4. The beeping sphere shocked the West, launched the Space Age and the Space Race, and led directly to NASA.", region:"Europe", tags:["sputnik","space","satellite","soviet"] },
{ id:114, title:"Cuban Missile Crisis — Nuclear Standoff", year:1962, lat:23.11, lng:-82.37, category:"war", impact:"HIGH", description:"The 13-day standoff between the US and USSR over Soviet nuclear missiles in Cuba brought the world closer to nuclear war than at any other point. Kennedy and Khrushchev reached a secret deal to step back.", region:"Americas", tags:["cuba","nuclear","cold war","kennedy","khrushchev"] },
{ id:115, title:"Assassination of John F. Kennedy", year:1963, lat:32.78, lng:-96.81, category:"politics", impact:"HIGH", description:"President Kennedy was shot and killed while riding in a motorcade through Dallas, Texas. His assassination shocked the world and remains one of history's most analysed and controversial events.", region:"Americas", tags:["kennedy","assassination","dallas","usa"] },
{ id:116, title:"Civil Rights Act — USA", year:1964, lat:38.9, lng:-77.04, category:"politics", impact:"HIGH", description:"President Johnson signed the Civil Rights Act, outlawing discrimination based on race, colour, religion, or national origin — the legislative culmination of the civil rights movement led by Martin Luther King Jr.", region:"Americas", tags:["civil rights","usa","equality","martin luther king"] },
{ id:117, title:"Yuri Gagarin — First Human in Space", year:1961, lat:51.27, lng:45.99, category:"science", impact:"HIGH", description:"Soviet cosmonaut Yuri Gagarin completed one orbit of Earth in 108 minutes aboard Vostok 1, becoming the first human in space. His flight shocked the West and accelerated the Space Race.", region:"Europe", tags:["gagarin","space","soviet","vostok"] },
{ id:118, title:"Apollo 11 — First Moon Landing", year:1969, lat:0.67, lng:23.47, category:"science", impact:"HIGH", description:"Neil Armstrong became the first human to walk on the Moon on July 20, 1969. 'One small step for man, one giant leap for mankind.' Over 600 million people watched the live broadcast.", region:"Global", tags:["moon landing","apollo 11","armstrong","nasa"] },
{ id:119, title:"Vietnam War Ends — Fall of Saigon", year:1975, lat:10.82, lng:106.63, category:"war", impact:"HIGH", description:"North Vietnamese tanks rolled into Saigon as the last Americans evacuated from the US Embassy roof. The communist victory ended a war that killed 3.5 million people and traumatised American society.", region:"Asia", tags:["saigon","vietnam","usa","war"] },
{ id:120, title:"Watergate — Nixon Resigns", year:1974, lat:38.9, lng:-77.04, category:"politics", impact:"HIGH", description:"Richard Nixon became the first US President to resign after the Watergate scandal revealed a White House cover-up. The scandal permanently transformed American political culture and public trust in government.", region:"Americas", tags:["watergate","nixon","usa","resignation"] },
{ id:121, title:"Iran Islamic Revolution", year:1979, lat:35.69, lng:51.39, category:"politics", impact:"HIGH", description:"Ayatollah Khomeini's Islamic Revolution overthrew the US-backed Shah and established the Islamic Republic of Iran, reshaping Middle Eastern geopolitics and beginning decades of US-Iran hostility.", region:"Middle East", tags:["iran","revolution","khomeini","shah"] },
{ id:122, title:"Soviet Invasion of Afghanistan", year:1979, lat:34.52, lng:69.18, category:"war", impact:"HIGH", description:"The Soviet Union invaded Afghanistan, triggering a decade-long occupation resisted by US-backed Mujahideen. The failed war contributed significantly to the eventual collapse of the Soviet Union.", region:"Asia", tags:["afghanistan","soviet","invasion","cold war"] },
{ id:123, title:"HIV/AIDS Pandemic Identified", year:1981, lat:34.05, lng:-118.24, category:"pandemic", impact:"HIGH", description:"The CDC published the first clinical evidence of what would be identified as AIDS. The global epidemic ultimately killed over 36 million people and drove extraordinary advances in antiviral medicine.", region:"Americas", tags:["aids","hiv","pandemic","disease"] },
{ id:124, title:"Chernobyl Nuclear Disaster", year:1986, lat:51.39, lng:30.1, category:"disaster", impact:"HIGH", description:"Reactor 4 at Chernobyl exploded, releasing radiation 400 times greater than the Hiroshima bomb. The worst nuclear disaster in history displaced 350,000 people and contributed to the Soviet Union's collapse.", region:"Europe", tags:["chernobyl","nuclear","disaster","ukraine"] },
{ id:125, title:"Tiananmen Square Massacre", year:1989, lat:39.91, lng:116.4, category:"politics", impact:"HIGH", description:"The Chinese military violently suppressed student-led pro-democracy protests in Beijing, killing hundreds to thousands. The iconic 'Tank Man' photograph became one of the defining images of the 20th century.", region:"Asia", tags:["tiananmen","china","democracy","massacre"] },
{ id:126, title:"Fall of the Berlin Wall", year:1989, lat:52.52, lng:13.38, category:"politics", impact:"HIGH", description:"East Germans began tearing down the Berlin Wall on November 9, symbolising the collapse of communist regimes across Eastern Europe. German reunification followed in 1990 and the Cold War effectively ended.", region:"Europe", tags:["berlin wall","fall","cold war","germany"] },
{ id:127, title:"Dissolution of the Soviet Union", year:1991, lat:55.76, lng:37.62, category:"politics", impact:"HIGH", description:"Gorbachev resigned and the Soviet flag was lowered over the Kremlin. The USSR dissolved into 15 independent states, ending the Cold War and the bipolar world order that had dominated global politics since 1945.", region:"Europe", tags:["soviet union","dissolution","gorbachev","russia"] },
{ id:128, title:"Gulf War — Operation Desert Storm", year:1991, lat:29.37, lng:47.98, category:"war", impact:"HIGH", description:"A US-led coalition drove Iraqi forces from Kuwait in a 100-hour ground campaign after five weeks of aerial bombardment, demonstrating American military dominance in the post-Cold War world.", region:"Middle East", tags:["gulf war","iraq","kuwait","usa"] },

// ══════════════════════════════════════
// POST-COLD WAR (1991–2010)
// ══════════════════════════════════════
{ id:129, title:"World Wide Web Invented at CERN", year:1991, lat:46.23, lng:6.05, category:"science", impact:"HIGH", description:"Tim Berners-Lee made the World Wide Web publicly available, launching the internet revolution that transformed commerce, communication, politics, and culture more thoroughly than any technology since the printing press.", region:"Europe", tags:["internet","www","berners-lee","cern"] },
{ id:130, title:"Rwandan Genocide", year:1994, lat:-1.94, lng:29.87, category:"war", impact:"HIGH", description:"Hutu extremists massacred approximately 800,000 Tutsis and moderate Hutus in 100 days — the fastest genocide in history. The international community's failure to intervene remains one of history's darkest failures.", region:"Africa", tags:["rwanda","genocide","massacre","africa"] },
{ id:131, title:"End of South African Apartheid — Mandela Elected", year:1994, lat:-25.75, lng:28.19, category:"politics", impact:"HIGH", description:"Nelson Mandela became South Africa's first Black president, ending 46 years of apartheid. His journey from 27-year prisoner to President became a global symbol of reconciliation and moral courage.", region:"Africa", tags:["mandela","apartheid","south africa","democracy"] },
{ id:132, title:"Dolly the Sheep — First Cloned Mammal", year:1996, lat:55.95, lng:-3.19, category:"science", impact:"HIGH", description:"Scientists at the Roslin Institute cloned Dolly from an adult somatic cell — the first mammal cloned from a non-reproductive cell. It raised profound ethical questions about the future of biotechnology.", region:"Europe", tags:["dolly","cloning","genetics","science"] },
{ id:133, title:"Euro Currency Launched", year:1999, lat:50.85, lng:4.35, category:"economy", impact:"HIGH", description:"Eleven European Union nations adopted the euro as a common currency — the largest monetary union in history. The eurozone expanded to 20 countries and became the world's second-most-held reserve currency.", region:"Europe", tags:["euro","europe","currency","eu"] },
{ id:134, title:"September 11 Terrorist Attacks", year:2001, lat:40.71, lng:-74.01, category:"war", impact:"HIGH", description:"Al-Qaeda terrorists hijacked four planes, destroying the World Trade Centre, hitting the Pentagon, and killing 2,977 people. The attacks launched the Global War on Terror that reshaped international relations for decades.", region:"Americas", tags:["9/11","terrorism","al-qaeda","usa"] },
{ id:135, title:"US Invasion of Iraq", year:2003, lat:33.34, lng:44.4, category:"war", impact:"HIGH", description:"A US-led coalition invaded Iraq claiming Saddam Hussein possessed WMDs. None were found. The war killed hundreds of thousands, destabilised the Middle East, and created the conditions for ISIS.", region:"Middle East", tags:["iraq","usa","invasion","saddam"] },
{ id:136, title:"Indian Ocean Boxing Day Tsunami", year:2004, lat:3.3, lng:95.98, category:"disaster", impact:"HIGH", description:"A 9.1 magnitude earthquake off Sumatra triggered a massive tsunami that struck 14 countries, killing 227,898 people — one of the deadliest natural disasters in recorded history.", region:"Asia", tags:["tsunami","indonesia","disaster","earthquake"] },
{ id:137, title:"Human Genome Project Completed", year:2003, lat:38.9, lng:-77.04, category:"science", impact:"HIGH", description:"The international Human Genome Project completed sequencing all 3.2 billion base pairs of the human genome — the blueprint for human life, opening the era of personalised medicine and gene therapy.", region:"Americas", tags:["genome","genetics","dna","medicine"] },
{ id:138, title:"Hurricane Katrina Devastates New Orleans", year:2005, lat:29.95, lng:-90.07, category:"disaster", impact:"HIGH", description:"Category 5 Hurricane Katrina struck New Orleans and the Gulf Coast, killing over 1,800 people and causing $125 billion in damage. The government's disastrous response exposed deep racial and economic inequalities.", region:"Americas", tags:["katrina","hurricane","new orleans","disaster"] },
{ id:139, title:"Barack Obama — First African American President", year:2008, lat:41.88, lng:-87.63, category:"politics", impact:"HIGH", description:"Barack Obama became the 44th President of the United States and the first African American to hold the office, winning by a substantial margin and representing a historic milestone in American race relations.", region:"Americas", tags:["obama","usa","president","historic"] },
{ id:140, title:"Global Financial Crisis — Lehman Brothers Collapses", year:2008, lat:40.71, lng:-74.01, category:"economy", impact:"HIGH", description:"The collapse of Lehman Brothers triggered the worst global financial crisis since the Great Depression, wiping out $20 trillion in wealth and causing millions of foreclosures worldwide.", region:"Americas", tags:["financial crisis","lehman","recession","economy"] },

// ══════════════════════════════════════
// MODERN ERA (2010–2024)
// ══════════════════════════════════════
{ id:141, title:"Arab Spring Begins in Tunisia", year:2010, lat:36.82, lng:10.17, category:"politics", impact:"HIGH", description:"Mohamed Bouazizi's self-immolation sparked a wave of pro-democracy protests across the Arab world, toppling governments in Tunisia, Egypt, Libya, and Yemen, and triggering civil wars in Syria and Libya.", region:"Africa", tags:["arab spring","tunisia","revolution","democracy"] },
{ id:142, title:"Fukushima Nuclear Disaster", year:2011, lat:37.42, lng:141.03, category:"disaster", impact:"HIGH", description:"A 9.0 magnitude earthquake and tsunami triggered three meltdowns at the Fukushima Daiichi nuclear plant — the worst nuclear accident since Chernobyl. 154,000 residents were evacuated.", region:"Asia", tags:["fukushima","nuclear","japan","earthquake"] },
{ id:143, title:"Syrian Civil War", year:2011, lat:33.51, lng:36.28, category:"war", impact:"HIGH", description:"Government crackdowns on Arab Spring protests escalated into a devastating civil war that killed over 500,000 and displaced half Syria's population, triggering Europe's largest refugee crisis since WWII.", region:"Middle East", tags:["syria","civil war","refugees","isis"] },
{ id:144, title:"Higgs Boson Discovered at CERN", year:2012, lat:46.23, lng:6.05, category:"science", impact:"HIGH", description:"Scientists at CERN's Large Hadron Collider confirmed the existence of the Higgs boson — the 'God particle' — confirming the Standard Model of particle physics and representing the greatest scientific achievement of the decade.", region:"Europe", tags:["higgs boson","cern","physics","god particle"] },
{ id:145, title:"Russia Annexes Crimea", year:2014, lat:44.95, lng:34.1, category:"war", impact:"HIGH", description:"Russia annexed Ukraine's Crimean Peninsula, triggering the worst East-West crisis since the Cold War and the first annexation of European territory since World War II.", region:"Europe", tags:["russia","crimea","ukraine","annexation"] },
{ id:146, title:"Paris Climate Agreement", year:2015, lat:48.85, lng:2.35, category:"politics", impact:"HIGH", description:"195 countries signed the Paris Agreement committing to limit global warming to below 2°C — the most ambitious international climate accord in history, though scientists warned targets remained insufficient.", region:"Global", tags:["paris agreement","climate change","environment","cop21"] },
{ id:147, title:"Brexit — UK Votes to Leave the EU", year:2016, lat:51.51, lng:-0.13, category:"politics", impact:"HIGH", description:"The United Kingdom voted 52–48% to leave the European Union, triggering years of political upheaval. Britain formally left on January 31, 2020, after the most divisive political debate in modern British history.", region:"Europe", tags:["brexit","uk","eu","referendum"] },
{ id:148, title:"SpaceX Lands First Reusable Rocket", year:2015, lat:28.57, lng:-80.65, category:"science", impact:"HIGH", description:"SpaceX's Falcon 9 rocket successfully landed its first stage after delivering payload to orbit, proving reusable rockets and beginning a revolution in the economics of spaceflight.", region:"Americas", tags:["spacex","rocket","reusable","musk"] },
{ id:149, title:"Gravitational Waves First Detected", year:2015, lat:30.56, lng:-90.77, category:"science", impact:"HIGH", description:"The LIGO detector confirmed gravitational waves from two colliding black holes 1.3 billion light-years away — confirming Einstein's 100-year-old prediction and opening a new way to observe the universe.", region:"Americas", tags:["gravitational waves","ligo","einstein","black holes"] },
{ id:150, title:"COVID-19 Global Pandemic", year:2020, lat:30.59, lng:114.31, category:"pandemic", impact:"HIGH", description:"The SARS-CoV-2 coronavirus spread globally from Wuhan, China, killing over 7 million people confirmed and causing the greatest global economic disruption since World War II.", region:"Global", tags:["covid","pandemic","coronavirus","china"] },
{ id:151, title:"Russia Invades Ukraine — Full-Scale War", year:2022, lat:50.45, lng:30.52, category:"war", impact:"HIGH", description:"Russia launched a full-scale invasion of Ukraine on February 24 — the largest military offensive in Europe since WWII. The war has killed tens of thousands, displaced millions, and reshaped European security.", region:"Europe", tags:["russia","ukraine","invasion","war"] },
{ id:152, title:"ChatGPT and the AI Revolution", year:2022, lat:37.34, lng:-121.89, category:"science", impact:"HIGH", description:"OpenAI released ChatGPT, reaching 100 million users in two months — the fastest-growing consumer application in history. The resulting AI revolution is transforming every industry worldwide.", region:"Americas", tags:["ai","chatgpt","openai","technology"] },
{ id:153, title:"Israel-Hamas War Begins", year:2023, lat:31.5, lng:34.47, category:"war", impact:"HIGH", description:"Hamas launched a devastating surprise attack on Israel on October 7, killing approximately 1,200 people. Israel's military response in Gaza triggered a major humanitarian crisis and intense international debate.", region:"Middle East", tags:["israel","hamas","gaza","war"] },

// ══════════════════════════════════════
// SCIENCE & DISCOVERY — ADDITIONAL
// ══════════════════════════════════════
{ id:154, title:"Archimedes Discovers Buoyancy Principle", year:-250, lat:37.08, lng:15.29, category:"science", impact:"MEDIUM", description:"Archimedes discovered the principle of buoyancy — that an object immersed in fluid is buoyed up by a force equal to the weight of fluid displaced — reportedly crying 'Eureka!' upon stepping into a bath.", region:"Europe", tags:["archimedes","buoyancy","physics","greek"] },
{ id:155, title:"Vesalius Publishes Human Anatomy Atlas", year:1543, lat:50.85, lng:4.35, category:"science", impact:"HIGH", description:"Andreas Vesalius published the first comprehensive and accurate description of human anatomy based on systematic dissection, correcting centuries of errors inherited from Galen and founding modern medicine.", region:"Europe", tags:["vesalius","anatomy","medicine","renaissance"] },
{ id:156, title:"William Harvey Describes Blood Circulation", year:1628, lat:51.51, lng:-0.13, category:"science", impact:"HIGH", description:"William Harvey proved that blood circulates continuously through the body, pumped by the heart. It overturned 1,400 years of Galenic medicine and is the foundation of modern cardiovascular understanding.", region:"Europe", tags:["harvey","circulation","heart","medicine"] },
{ id:157, title:"Edward Jenner Develops Smallpox Vaccination", year:1796, lat:51.8, lng:-2.24, category:"science", impact:"HIGH", description:"Edward Jenner discovered that cowpox inoculation provided protection against smallpox, creating the world's first vaccine. His work eventually led to the eradication of smallpox in 1980.", region:"Europe", tags:["jenner","smallpox","vaccine","medicine"] },
{ id:158, title:"Mendeleev Creates the Periodic Table", year:1869, lat:59.93, lng:30.32, category:"science", impact:"HIGH", description:"Mendeleev arranged the known elements in order of atomic weight, revealing a periodic pattern and predicting the existence of undiscovered elements — one of science's greatest feats of systematic foresight.", region:"Europe", tags:["mendeleev","periodic table","chemistry","elements"] },
{ id:159, title:"Röntgen Discovers X-Rays", year:1895, lat:49.8, lng:9.93, category:"science", impact:"HIGH", description:"Wilhelm Röntgen discovered X-rays while experimenting with cathode ray tubes, taking the first X-ray photograph of his wife's hand. Medical imaging was born, and X-rays were in clinical use within a year.", region:"Europe", tags:["xray","röntgen","medical imaging","physics"] },
{ id:160, title:"Einstein Publishes General Relativity", year:1915, lat:52.52, lng:13.41, category:"science", impact:"HIGH", description:"Einstein's general theory of relativity described gravity as a curvature of spacetime, predicting black holes, gravitational waves, and the expanding universe — all confirmed by observation decades later.", region:"Europe", tags:["einstein","general relativity","gravity","spacetime"] },
{ id:161, title:"Hubble Proves the Universe is Expanding", year:1929, lat:34.22, lng:-118.06, category:"science", impact:"HIGH", description:"Edwin Hubble's observations of distant galaxies showed they are all moving away from us at speeds proportional to their distance, proving the universe is expanding and implying the Big Bang.", region:"Americas", tags:["hubble","universe","expanding","cosmology"] },
{ id:162, title:"First Nuclear Chain Reaction — Manhattan Project", year:1942, lat:41.79, lng:-87.6, category:"science", impact:"HIGH", description:"Enrico Fermi achieved the first self-sustaining nuclear chain reaction at the University of Chicago, beginning the atomic age and paving the way for both nuclear weapons and nuclear power.", region:"Americas", tags:["nuclear","fermi","manhattan project","atomic"] },
{ id:163, title:"First Test-Tube Baby Born", year:1978, lat:53.89, lng:-2.24, category:"science", impact:"HIGH", description:"Louise Brown, the world's first baby conceived through in vitro fertilisation (IVF), was born in England. IVF has since helped over 10 million people with fertility problems have children.", region:"Europe", tags:["ivf","test tube baby","medicine","reproduction"] },
{ id:164, title:"First Image of a Black Hole", year:2019, lat:33.7, lng:-117.82, category:"science", impact:"HIGH", description:"The Event Horizon Telescope produced the first-ever image of a black hole — M87* at the centre of galaxy Messier 87, 55 million light-years away — confirming key predictions of general relativity.", region:"Americas", tags:["black hole","event horizon","astronomy","einstein"] },
{ id:165, title:"James Webb Space Telescope First Images", year:2022, lat:28.57, lng:-80.65, category:"science", impact:"HIGH", description:"NASA released the first full-colour images from the James Webb Space Telescope, showing galaxies from 13.5 billion years ago with unprecedented clarity, transforming our view of the early universe.", region:"Americas", tags:["james webb","telescope","nasa","space"] },

// ══════════════════════════════════════
// DISASTERS — ADDITIONAL
// ══════════════════════════════════════
{ id:166, title:"Lisbon Earthquake and Tsunami", year:1755, lat:38.72, lng:-9.14, category:"disaster", impact:"HIGH", description:"A massive earthquake, tsunami, and fires destroyed 85% of Lisbon and killed 40,000–50,000 people on All Saints' Day. The disaster shook Enlightenment optimism and inspired Voltaire's Candide.", region:"Europe", tags:["lisbon","earthquake","tsunami","portugal"] },
{ id:167, title:"Great San Francisco Earthquake", year:1906, lat:37.77, lng:-122.42, category:"disaster", impact:"HIGH", description:"A magnitude 7.9 earthquake and subsequent fires destroyed 80% of San Francisco, killing approximately 3,000 people and leaving 300,000 homeless — one of the deadliest disasters in US history.", region:"Americas", tags:["san francisco","earthquake","disaster","fire"] },
{ id:168, title:"Great Kanto Earthquake — Tokyo Destroyed", year:1923, lat:35.69, lng:139.69, category:"disaster", impact:"HIGH", description:"A magnitude 7.9 earthquake struck the Tokyo-Yokohama metropolitan area, killing approximately 143,000 people. The resulting fires destroyed much of both cities and set back Japanese economic development.", region:"Asia", tags:["tokyo","earthquake","japan","disaster"] },
{ id:169, title:"Bhopal Gas Disaster", year:1984, lat:23.23, lng:77.43, category:"disaster", impact:"HIGH", description:"A gas leak from the Union Carbide pesticide plant in Bhopal, India killed approximately 3,787 people immediately and thousands more over subsequent months. It remains the world's worst industrial accident.", region:"Asia", tags:["bhopal","disaster","industrial","india"] },
{ id:170, title:"Haiti Earthquake — 300,000 Dead", year:2010, lat:18.54, lng:-72.34, category:"disaster", impact:"HIGH", description:"A 7.0 magnitude earthquake struck 25km west of Port-au-Prince, killing 100,000–316,000 people and leaving 1.5 million homeless in one of the poorest nations on Earth.", region:"Americas", tags:["haiti","earthquake","disaster","2010"] },

// ══════════════════════════════════════
// CULTURE & ARTS — ADDITIONAL
// ══════════════════════════════════════
{ id:171, title:"Renaissance Begins in Florence", year:1400, lat:43.78, lng:11.25, category:"culture", impact:"HIGH", description:"The Renaissance — a cultural rebirth inspired by classical antiquity — began in Florence under Medici patronage, transforming art, architecture, literature, and science across Europe.", region:"Europe", tags:["renaissance","florence","medici","art"] },
{ id:172, title:"Leonardo da Vinci Paints the Mona Lisa", year:1503, lat:43.78, lng:11.25, category:"culture", impact:"HIGH", description:"Leonardo began painting the Mona Lisa in Florence, a work that exemplifies Renaissance ideals of portraiture and psychological depth. It is today the world's most visited painting.", region:"Europe", tags:["mona lisa","leonardo","renaissance","art"] },
{ id:173, title:"Shakespeare Writes Hamlet", year:1600, lat:51.51, lng:-0.13, category:"culture", impact:"HIGH", description:"William Shakespeare wrote Hamlet, widely considered the greatest play in the English language. Its exploration of indecision, mortality, and revenge has made it the most performed play in history.", region:"Europe", tags:["shakespeare","hamlet","theatre","england"] },
{ id:174, title:"Taj Mahal Construction Begins", year:1632, lat:27.17, lng:78.04, category:"culture", impact:"HIGH", description:"Mughal Emperor Shah Jahan ordered construction of the Taj Mahal as a mausoleum for his wife Mumtaz Mahal. 20,000 workers took 20 years to complete the white marble masterpiece.", region:"Asia", tags:["taj mahal","mughal","india","architecture"] },
{ id:175, title:"Beethoven's Ninth Symphony Premiered", year:1824, lat:48.21, lng:16.37, category:"culture", impact:"HIGH", description:"Ludwig van Beethoven, completely deaf, completed and premiered his Ninth Symphony in Vienna, including the 'Ode to Joy'. It is widely considered the greatest musical composition in the Western tradition.", region:"Europe", tags:["beethoven","symphony","music","vienna"] },
{ id:176, title:"First Photograph Taken by Niépce", year:1826, lat:46.87, lng:4.87, category:"culture", impact:"HIGH", description:"Joseph Nicéphore Niépce captured the world's first permanent photograph, 'View from the Window at Le Gras', requiring an 8-hour exposure, fundamentally transforming how humans record memory and history.", region:"Europe", tags:["photography","first photograph","invention","france"] },
{ id:177, title:"Television Publicly Demonstrated", year:1926, lat:51.51, lng:-0.13, category:"science", impact:"HIGH", description:"John Logie Baird demonstrated the world's first working television system in London. Television became the 20th century's dominant medium for news and entertainment, reaching billions of homes worldwide.", region:"Europe", tags:["television","baird","invention","media"] },
{ id:178, title:"First Feature Film Released in Australia", year:1906, lat:-37.82, lng:144.96, category:"culture", impact:"MEDIUM", description:"'The Story of the Kelly Gang' was released as the world's first feature-length film. The film industry that followed became the 20th century's dominant art form and cultural influence worldwide.", region:"Oceania", tags:["cinema","film","australia","first"] },
{ id:179, title:"Jazz Age and Harlem Renaissance", year:1920, lat:40.81, lng:-73.95, category:"culture", impact:"HIGH", description:"The Harlem Renaissance produced an extraordinary flowering of African American literature, art, and music in New York. Writers like Langston Hughes gave Black America a powerful new cultural identity.", region:"Americas", tags:["harlem renaissance","jazz","black culture","new york"] },

// ══════════════════════════════════════
// ECONOMY & TRADE — ADDITIONAL
// ══════════════════════════════════════
{ id:180, title:"Silk Road Opens — Han Dynasty", year:-130, lat:36.06, lng:103.79, category:"economy", impact:"HIGH", description:"Emperor Wu of Han opened the Silk Road, the network of trade routes connecting China to the Mediterranean. For 1,500 years it facilitated the exchange of silk, spices, ideas, religions, and diseases.", region:"Asia", tags:["silk road","china","trade","han dynasty"] },
{ id:181, title:"Amsterdam Stock Exchange — First in World", year:1602, lat:52.37, lng:4.9, category:"economy", impact:"HIGH", description:"The Dutch East India Company founded the Amsterdam Stock Exchange, the world's first modern stock exchange, issuing shares to the public and pioneering concepts still central to modern capital markets.", region:"Europe", tags:["amsterdam","stock exchange","voc","dutch"] },
{ id:182, title:"First Transatlantic Telegraph Cable", year:1858, lat:52.26, lng:-10.21, category:"economy", impact:"HIGH", description:"A telegraph cable was successfully laid across the Atlantic, allowing messages to cross in hours rather than weeks. Though it failed after three weeks, it demonstrated the feasibility of global instant communication.", region:"Europe", tags:["telegraph","transatlantic","communication","cable"] },
{ id:183, title:"OPEC Oil Embargo Creates Energy Crisis", year:1973, lat:22.25, lng:45.57, category:"economy", impact:"HIGH", description:"Arab OPEC members imposed an oil embargo on the US and Western allies in response to support for Israel. Oil prices quadrupled, causing the worst economic crisis since the Great Depression.", region:"Middle East", tags:["opec","oil embargo","energy crisis","economy"] },
{ id:184, title:"Deng Xiaoping Opens China to Investment", year:1978, lat:39.9, lng:116.4, category:"economy", impact:"HIGH", description:"Deng Xiaoping launched economic reforms opening China to foreign investment and market mechanisms, eventually lifting 800 million people out of poverty and creating the world's second-largest economy.", region:"Asia", tags:["china","deng xiaoping","economic reform","growth"] },
{ id:185, title:"Apple II Launches Personal Computer Revolution", year:1977, lat:37.33, lng:-122.03, category:"science", impact:"HIGH", description:"Apple released the Apple II, one of the first mass-produced personal computers, launching the PC revolution that transformed how humans work, communicate, and access information.", region:"Americas", tags:["apple","personal computer","technology","silicon valley"] },
{ id:186, title:"Global Financial Crisis — Dot-Com Bubble Bursts", year:2000, lat:37.39, lng:-121.97, category:"economy", impact:"HIGH", description:"The collapse of technology stock valuations erased $5 trillion in stock market value as investors realised most internet companies were unprofitable, ending the 1990s boom.", region:"Americas", tags:["dot-com","bubble","internet","nasdaq"] },
{ id:187, title:"Facebook Founded — Social Media Born", year:2004, lat:42.37, lng:-71.11, category:"science", impact:"HIGH", description:"Mark Zuckerberg launched Facebook at Harvard University. The social network grew to 3 billion active users, fundamentally changing how information spreads in modern society.", region:"Americas", tags:["facebook","social media","zuckerberg","internet"] },

// ══════════════════════════════════════
// RELIGION & PHILOSOPHY — ADDITIONAL
// ══════════════════════════════════════
{ id:188, title:"Construction of Solomon's Temple", year:-960, lat:31.78, lng:35.23, category:"religion", impact:"HIGH", description:"King Solomon built the First Temple in Jerusalem as the house of the Ark of the Covenant, representing the spiritual and national centre of Judaism. Its memory endures 3,000 years later.", region:"Middle East", tags:["solomon","temple","jerusalem","judaism"] },
{ id:189, title:"Crucifixion of Jesus of Nazareth", year:33, lat:31.78, lng:35.23, category:"religion", impact:"HIGH", description:"Jesus of Nazareth was crucified in Jerusalem under Roman authority. Christians believe he rose from the dead three days later — the central event of Christian theology and the foundation of the world's largest religion.", region:"Middle East", tags:["crucifixion","jesus","christianity","jerusalem"] },
{ id:190, title:"Sunni-Shia Split — Battle of Karbala", year:680, lat:32.62, lng:44.02, category:"religion", impact:"HIGH", description:"The Battle of Karbala, in which Husayn ibn Ali was killed, cemented the division between Sunni and Shia Islam that persists today. Karbala is the holiest city for Shia Muslims worldwide.", region:"Middle East", tags:["karbala","shia","sunni","islam"] },
{ id:191, title:"Pope Urban II's Crusade Speech", year:1095, lat:45.76, lng:3.1, category:"religion", impact:"HIGH", description:"Pope Urban II's speech at the Council of Clermont called on European Christians to take up arms to liberate the Holy Land, prompting tens of thousands to take the cross and launching two centuries of crusading.", region:"Europe", tags:["crusade","pope urban","clermont","holy land"] },
{ id:192, title:"King James Bible Published", year:1611, lat:51.51, lng:-0.13, category:"religion", impact:"HIGH", description:"The King James Version of the Bible was published, commissioned by King James I. Its majestic prose shaped the English language as profoundly as Shakespeare, remaining the standard English Bible for 300 years.", region:"Europe", tags:["king james bible","english","religion","protestant"] },
{ id:193, title:"Vatican II — Catholic Church Reforms", year:1962, lat:41.9, lng:12.45, category:"religion", impact:"HIGH", description:"Pope John XXIII convened the Second Vatican Council, modernising Catholic liturgy, improving relations with other faiths, and recognising religious freedom — a dramatic update of a 2,000-year-old institution.", region:"Europe", tags:["vatican ii","catholic","pope john","reform"] },

// ══════════════════════════════════════
// EXPLORATION — ADDITIONAL
// ══════════════════════════════════════
{ id:194, title:"Ibn Battuta Begins 29-Year World Journey", year:1325, lat:35.12, lng:-5.83, category:"exploration", impact:"MEDIUM", description:"The Moroccan scholar Ibn Battuta departed Tangier on a 29-year journey covering 117,000km across the Islamic world, India, China, and sub-Saharan Africa — the longest known pre-modern journey.", region:"Africa", tags:["ibn battuta","exploration","journey","medieval"] },
{ id:195, title:"Bartholomew Dias Rounds Cape of Good Hope", year:1488, lat:-34.36, lng:18.47, category:"exploration", impact:"HIGH", description:"Portuguese navigator Bartholomew Dias became the first European to round the southern tip of Africa, opening the sea route to Asia and enabling Vasco da Gama's voyage to India a decade later.", region:"Africa", tags:["dias","cape of good hope","portugal","exploration"] },
{ id:196, title:"Captain Cook's Pacific Voyage", year:1768, lat:-36.87, lng:174.77, category:"exploration", impact:"HIGH", description:"James Cook's Endeavour voyage mapped the Pacific including New Zealand and eastern Australia, collected thousands of new botanical specimens, and dramatically expanded European knowledge of the world's largest ocean.", region:"Oceania", tags:["cook","pacific","exploration","australia"] },
{ id:197, title:"Lewis and Clark Explore American West", year:1804, lat:38.63, lng:-90.19, category:"exploration", impact:"HIGH", description:"Meriwether Lewis and William Clark led the Corps of Discovery from Missouri to the Pacific Ocean, mapping the Louisiana Territory, establishing relations with Native tribes, and opening the American West.", region:"Americas", tags:["lewis and clark","usa","exploration","west"] },
{ id:198, title:"Amundsen Reaches South Pole First", year:1911, lat:-90.0, lng:0.0, category:"exploration", impact:"HIGH", description:"Norwegian explorer Roald Amundsen's team reached the South Pole on December 14, beating Scott's British expedition by five weeks. Scott and his four companions perished on the return journey.", region:"Global", tags:["amundsen","south pole","antarctica","scott"] },
{ id:199, title:"Lindbergh's Solo Transatlantic Flight", year:1927, lat:48.85, lng:2.35, category:"exploration", impact:"HIGH", description:"Lindbergh flew non-stop from New York to Paris in 33.5 hours in the 'Spirit of St. Louis', winning the $25,000 Orteig Prize and transforming aviation into a serious commercial industry.", region:"Europe", tags:["lindbergh","transatlantic","flight","paris"] },
{ id:200, title:"First Ascent of Mount Everest", year:1953, lat:27.99, lng:86.93, category:"exploration", impact:"MEDIUM", description:"Edmund Hillary and Tenzing Norgay reached the summit of Everest — the world's highest peak at 8,849m — on May 29. The news reached London the morning of Queen Elizabeth II's coronation.", region:"Asia", tags:["everest","hillary","tenzing","mountaineering"] },

// ══════════════════════════════════════
// WARS — ADDITIONAL
// ══════════════════════════════════════
{ id:201, title:"Mongol Invasion of Europe", year:1241, lat:47.5, lng:21.62, category:"war", impact:"HIGH", description:"Batu Khan's Mongol army destroyed Kraków, Warsaw, and Budapest, defeating Polish-German forces at Legnica. Only the death of the Great Khan halted the invasion, possibly saving Western Europe.", region:"Europe", tags:["mongols","invasion","poland","europe"] },
{ id:202, title:"Siege of Vienna — Ottoman Empire Halted", year:1683, lat:48.21, lng:16.37, category:"war", impact:"HIGH", description:"A Polish-led Holy League army under King John III Sobieski defeated the Ottoman besiegers of Vienna. The victory halted the Ottoman advance into Europe and began the long Ottoman decline.", region:"Europe", tags:["vienna","ottoman","siege","poland"] },
{ id:203, title:"Seven Years War — First Global Conflict", year:1756, lat:52.52, lng:13.41, category:"war", impact:"HIGH", description:"The Seven Years War was fought across five continents, involving every major European power. Britain emerged as the dominant global colonial power, gaining Canada, India, and other territories.", region:"Europe", tags:["seven years war","britain","france","global"] },
{ id:204, title:"Battle of Gettysburg — Civil War Turning Point", year:1863, lat:39.81, lng:-77.23, category:"war", impact:"HIGH", description:"The three-day battle at Gettysburg was the deadliest of the American Civil War and a decisive turning point. The Confederate defeat ended its last major Northern offensive. Lincoln's Address followed.", region:"Americas", tags:["gettysburg","civil war","usa","union"] },
{ id:205, title:"Ottoman Armenian Genocide", year:1915, lat:39.92, lng:32.85, category:"war", impact:"HIGH", description:"The Ottoman government systematically deported and massacred the Armenian population, killing an estimated 600,000–1.5 million people in what many nations formally recognise as genocide.", region:"Middle East", tags:["armenia","genocide","ottoman","turkey"] },
{ id:206, title:"Falklands War", year:1982, lat:-51.7, lng:-57.85, category:"war", impact:"MEDIUM", description:"Argentina seized the British Falkland Islands, triggering a naval task force from Britain. After 74 days of fighting, Argentina surrendered. The war reinvigorated Thatcher's government.", region:"Americas", tags:["falklands","argentina","britain","thatcher"] },
{ id:207, title:"Siege of Sarajevo — Bosnian War", year:1992, lat:43.85, lng:18.41, category:"war", impact:"HIGH", description:"Sarajevo endured the longest siege of a capital city in modern warfare — 1,425 days — during the Bosnian War. Over 13,000 people died in the conflict that marked the brutal breakup of Yugoslavia.", region:"Europe", tags:["sarajevo","bosnia","siege","yugoslav"] },
{ id:208, title:"Rwandan Genocide — 100 Days of Killing", year:1994, lat:-1.94, lng:29.87, category:"war", impact:"HIGH", description:"In just 100 days, Hutu extremists killed approximately 800,000 Tutsi civilians — the fastest rate of mass killing in recorded history. The UN and Western nations failed to intervene.", region:"Africa", tags:["rwanda","genocide","africa","1994"] },
{ id:209, title:"Kosovo War — NATO Intervention", year:1999, lat:42.67, lng:21.17, category:"war", impact:"HIGH", description:"NATO launched its first combat operation against Serbian forces in Kosovo without UN authorisation, establishing the controversial precedent that the international community could intervene in civil conflicts.", region:"Europe", tags:["kosovo","nato","serbia","war"] },
{ id:210, title:"US Invasion of Afghanistan", year:2001, lat:34.52, lng:69.18, category:"war", impact:"HIGH", description:"A US-led coalition invaded Afghanistan in response to 9/11, quickly defeating the Taliban government. The resulting 20-year occupation ended with the Taliban's return in 2021 — America's longest war.", region:"Asia", tags:["afghanistan","usa","9/11","taliban"] },
{ id:211, title:"ISIS Declares Caliphate in Iraq and Syria", year:2014, lat:36.36, lng:43.16, category:"war", impact:"HIGH", description:"The Islamic State declared a caliphate spanning large areas of Iraq and Syria, capturing Mosul and shocking the world with the speed of its advance and the brutality of its methods.", region:"Middle East", tags:["isis","caliphate","syria","iraq"] },
{ id:212, title:"Yemen Civil War", year:2015, lat:15.35, lng:44.21, category:"war", impact:"HIGH", description:"A Saudi-led coalition intervened in Yemen's civil war creating what the UN called the world's worst humanitarian crisis. Over 150,000 people have died and millions face famine.", region:"Middle East", tags:["yemen","civil war","saudi","humanitarian"] },

// ══════════════════════════════════════
// POLITICS — ADDITIONAL
// ══════════════════════════════════════
{ id:213, title:"US Constitution Ratified", year:1788, lat:38.9, lng:-77.04, category:"politics", impact:"HIGH", description:"The US Constitution was ratified, creating the world's oldest national constitution still in use. Its framework of federal government with separation of powers became the model for constitutions worldwide.", region:"Americas", tags:["constitution","usa","federalism","democracy"] },
{ id:214, title:"Mussolini Establishes First Fascist Dictatorship", year:1922, lat:41.9, lng:12.49, category:"politics", impact:"HIGH", description:"Benito Mussolini led the March on Rome and became Prime Minister. By 1925 he had established a fascist dictatorship — the first in Europe and the template for Hitler's subsequent rise to power.", region:"Europe", tags:["mussolini","fascism","italy","dictatorship"] },
{ id:215, title:"Churchill Becomes British Prime Minister", year:1940, lat:51.5, lng:-0.13, category:"politics", impact:"HIGH", description:"Winston Churchill replaced Neville Chamberlain as Prime Minister as Germany overran Western Europe. His wartime leadership and speeches became a defining symbol of Allied resolve and British national character.", region:"Europe", tags:["churchill","britain","wwii","prime minister"] },
{ id:216, title:"Marshall Plan — Rebuilding Europe", year:1948, lat:52.52, lng:13.41, category:"economy", impact:"HIGH", description:"The US Marshall Plan provided $13.3 billion to rebuild war-devastated Western European economies, preventing communist movements from gaining power and laying the foundation for European prosperity and integration.", region:"Europe", tags:["marshall plan","usa","europe","reconstruction"] },
{ id:217, title:"European Union Founded — Maastricht Treaty", year:1993, lat:50.85, lng:5.69, category:"politics", impact:"HIGH", description:"The Maastricht Treaty established the European Union, creating European citizenship, laying the groundwork for a single currency, and committing members to political as well as economic integration.", region:"Europe", tags:["european union","maastricht","europe","integration"] },
{ id:218, title:"Good Friday Agreement — Northern Ireland Peace", year:1998, lat:54.6, lng:-5.93, category:"politics", impact:"HIGH", description:"The Belfast Agreement ended 30 years of sectarian violence in Northern Ireland that had killed over 3,500 people. It established power-sharing government and became a model for negotiated peace settlements.", region:"Europe", tags:["good friday","northern ireland","peace","belfast"] },
{ id:219, title:"George W. Bush Wins Contested US Election", year:2000, lat:25.77, lng:-80.19, category:"politics", impact:"MEDIUM", description:"The disputed presidential election between George W. Bush and Al Gore was decided by the Supreme Court after a Florida recount controversy. Bush won the Electoral College despite losing the popular vote.", region:"Americas", tags:["usa","election","bush","gore","florida"] },
{ id:220, title:"George Floyd Killing Sparks BLM Movement", year:2020, lat:44.97, lng:-93.26, category:"politics", impact:"HIGH", description:"The killing of George Floyd by a Minneapolis police officer sparked global Black Lives Matter protests in over 60 countries — the largest protest movement in US history and a global reckoning with systemic racism.", region:"Americas", tags:["george floyd","blm","racial justice","protests"] },

// ══════════════════════════════════════
// PANDEMICS — ADDITIONAL
// ══════════════════════════════════════
{ id:221, title:"Justinian Plague Kills Millions in Europe", year:541, lat:36.85, lng:30.7, category:"pandemic", impact:"HIGH", description:"The first confirmed bubonic plague outbreak swept the Mediterranean world, killing perhaps 25 million people and permanently weakening the Byzantine Empire, altering the course of Mediterranean history.", region:"Europe", tags:["plague","justinian","epidemic","byzantium"] },
{ id:222, title:"Black Death Spreads to England", year:1348, lat:51.51, lng:-0.13, category:"pandemic", impact:"HIGH", description:"The bubonic plague reached England, killing between one-third and one-half of the entire population. The labour shortage dramatically raised wages and began the unravelling of the feudal social order.", region:"Europe", tags:["black death","england","plague","feudalism"] },
{ id:223, title:"Cholera Pandemic — John Snow and the Broad Street Pump", year:1854, lat:51.51, lng:-0.14, category:"pandemic", impact:"HIGH", description:"John Snow traced a cholera outbreak to a contaminated water pump in Soho, London, founding the science of epidemiology. His discovery that cholera spread through contaminated water transformed public health.", region:"Europe", tags:["cholera","john snow","london","epidemiology"] },
{ id:224, title:"Third Plague Pandemic Kills 12 Million in India", year:1896, lat:18.96, lng:72.82, category:"pandemic", impact:"HIGH", description:"The third bubonic plague pandemic originated in Yunnan, China and spread worldwide, killing 12 million people mostly in India. It was during this pandemic that the bubonic plague bacillus Yersinia pestis was identified.", region:"Asia", tags:["plague","india","pandemic","bubonic"] },
{ id:225, title:"SARS Outbreak — First 21st Century Pandemic Scare", year:2003, lat:22.32, lng:114.17, category:"pandemic", impact:"MEDIUM", description:"Severe Acute Respiratory Syndrome spread from China to 26 countries, killing 774 people and raising global alarm about novel respiratory viruses — a warning that went unheeded before COVID-19.", region:"Asia", tags:["sars","pandemic","china","respiratory"] },
{ id:226, title:"Ebola Outbreak in West Africa", year:2014, lat:9.5, lng:-13.5, category:"pandemic", impact:"HIGH", description:"The largest Ebola epidemic in history killed 11,310 people in Guinea, Liberia, and Sierra Leone over two years, overwhelming fragile health systems and exposing the vulnerability of West Africa to epidemic disease.", region:"Africa", tags:["ebola","west africa","epidemic","virus"] },
{ id:227, title:"Zika Virus Pandemic", year:2015, lat:-15.78, lng:-47.93, category:"pandemic", impact:"MEDIUM", description:"The Zika virus spread rapidly through the Americas, linked to microcephaly in newborns. Brazil declared a national emergency and the WHO declared a global health emergency, prompting a major research response.", region:"Americas", tags:["zika","pandemic","brazil","virus"] },
{ id:228, title:"Mpox (Monkeypox) Global Outbreak", year:2022, lat:40.71, lng:-74.01, category:"pandemic", impact:"MEDIUM", description:"Mpox spread globally outside Africa for the first time, with over 87,000 confirmed cases in 110 countries. The WHO declared it a global health emergency, raising concerns about the potential for future zoonotic pandemics.", region:"Global", tags:["mpox","monkeypox","pandemic","virus"] },

// ══════════════════════════════════════
// ENVIRONMENT & CLIMATE
// ══════════════════════════════════════
{ id:229, title:"Industrial Smog Kills 12,000 in London", year:1952, lat:51.51, lng:-0.13, category:"disaster", impact:"HIGH", description:"A cold fog combined with coal smoke created a lethal smog that blanketed London for five days, killing 12,000 people. It led directly to the Clean Air Act of 1956, the world's first modern air pollution law.", region:"Europe", tags:["london smog","pollution","disaster","clean air"] },
{ id:230, title:"Exxon Valdez Oil Spill in Alaska", year:1989, lat:60.84, lng:-146.87, category:"disaster", impact:"HIGH", description:"The Exxon Valdez tanker ran aground in Prince William Sound, Alaska, spilling 11 million gallons of oil and devastating a pristine ecosystem. It galvanised the modern environmental movement.", region:"Americas", tags:["exxon valdez","oil spill","environment","alaska"] },
{ id:231, title:"Ozone Layer Hole Discovered", year:1985, lat:-90.0, lng:0.0, category:"science", impact:"HIGH", description:"British scientists discovered a dramatic thinning of the ozone layer above Antarctica, shocking the world into action. The resulting Montreal Protocol (1987) became the most successful international environmental agreement.", region:"Global", tags:["ozone","climate","antarctica","environment"] },
{ id:232, title:"Deepwater Horizon — Largest Marine Oil Spill", year:2010, lat:28.74, lng:-88.39, category:"disaster", impact:"HIGH", description:"The BP Deepwater Horizon rig exploded and sank, releasing 4.9 million barrels of oil into the Gulf of Mexico over 87 days — the largest marine oil spill in history, causing catastrophic ecological damage.", region:"Americas", tags:["deepwater horizon","oil spill","gulf of mexico","bp"] },
{ id:233, title:"Amazon Rainforest Fires Crisis", year:2019, lat:-3.47, lng:-62.22, category:"disaster", impact:"HIGH", description:"Record-breaking fires in the Amazon rainforest, fuelled by clearing for agriculture, burned an area larger than many European nations, drawing global attention to the accelerating destruction of Earth's lungs.", region:"Americas", tags:["amazon","fire","deforestation","climate"] },
{ id:234, title:"Australia's Black Summer Megafires", year:2019, lat:-33.87, lng:151.21, category:"disaster", impact:"HIGH", description:"Australia's Black Summer bushfires burned over 18 million hectares, killing an estimated 3 billion animals and destroying over 3,000 homes. Scientists directly linked the unprecedented fires to climate change.", region:"Oceania", tags:["australia","bushfire","climate","disaster"] },

// ══════════════════════════════════════
// SPACE & TECHNOLOGY
// ══════════════════════════════════════
{ id:235, title:"First Satellite Image of Earth — The Blue Marble", year:1972, lat:28.57, lng:-80.65, category:"exploration", impact:"HIGH", description:"Apollo 17 astronauts photographed 'The Blue Marble' — the most widely reproduced photograph in history showing Earth as a fragile sphere in space. The image galvanised the environmental movement.", region:"Global", tags:["blue marble","earth","photo","apollo 17"] },
{ id:236, title:"Voyager 1 Enters Interstellar Space", year:1977, lat:28.57, lng:-80.65, category:"exploration", impact:"HIGH", description:"NASA launched Voyager 1, which flew past Jupiter and Saturn before becoming the first human-made object to enter interstellar space in 2012. It continues to send data from over 23 billion km from Earth.", region:"Americas", tags:["voyager","nasa","space","interstellar"] },
{ id:237, title:"Hubble Space Telescope Launched", year:1990, lat:28.57, lng:-80.65, category:"science", impact:"HIGH", description:"NASA's Hubble Space Telescope was launched into orbit, eventually providing the deepest views of the universe ever obtained and transforming our understanding of the age, size, and structure of the cosmos.", region:"Americas", tags:["hubble","telescope","nasa","space"] },
{ id:238, title:"International Space Station Begins Construction", year:1998, lat:28.57, lng:-80.65, category:"science", impact:"HIGH", description:"The International Space Station began construction, ultimately becoming the largest structure ever assembled in space and a symbol of unprecedented international scientific cooperation involving 15 nations.", region:"Global", tags:["iss","space station","nasa","international"] },
{ id:239, title:"Mars Rovers Explore the Red Planet", year:2004, lat:28.57, lng:-80.65, category:"science", impact:"MEDIUM", description:"NASA's Spirit and Opportunity rovers landed on Mars, dramatically extending our knowledge of the planet's geological history and confirming ancient water activity — raising hopes for past microbial life.", region:"Americas", tags:["mars","rover","nasa","space"] },
{ id:240, title:"CRISPR Gene Editing Developed", year:2012, lat:37.87, lng:-122.26, category:"science", impact:"HIGH", description:"Jennifer Doudna and Emmanuelle Charpentier developed CRISPR-Cas9 as a precise gene-editing tool, launching a revolution in medicine and agriculture. The technique could eliminate hereditary diseases within decades.", region:"Americas", tags:["crispr","gene editing","genetics","medicine"] },

// ══════════════════════════════════════
// SOCIETY & HUMAN RIGHTS
// ══════════════════════════════════════
{ id:241, title:"Women's Suffrage — New Zealand First", year:1893, lat:-41.29, lng:174.78, category:"politics", impact:"HIGH", description:"New Zealand became the first self-governing country to grant women the right to vote on September 19, 1893 — a milestone in the long struggle for gender equality that took decades more to spread worldwide.", region:"Oceania", tags:["women's suffrage","new zealand","votes","rights"] },
{ id:242, title:"Universal Declaration of Human Rights", year:1948, lat:48.87, lng:2.33, category:"politics", impact:"HIGH", description:"The UN General Assembly adopted the Universal Declaration of Human Rights, proclaiming 30 fundamental rights belonging to all people regardless of nationality, sex, religion, or any other status.", region:"Europe", tags:["human rights","un","declaration","1948"] },
{ id:243, title:"Rosa Parks Refuses to Give Up Her Bus Seat", year:1955, lat:32.37, lng:-86.3, category:"politics", impact:"HIGH", description:"Rosa Parks' refusal to give up her bus seat to a white passenger in Montgomery, Alabama catalysed the 381-day Montgomery Bus Boycott and became an iconic act of civil rights resistance.", region:"Americas", tags:["rosa parks","civil rights","montgomery","usa"] },
{ id:244, title:"Stonewall Riots — LGBT Rights Movement", year:1969, lat:40.73, lng:-74.0, category:"politics", impact:"HIGH", description:"Police raided the Stonewall Inn in New York City, prompting resistance from LGBTQ patrons. The resulting riots catalysed the modern gay rights movement and are commemorated annually through Pride marches worldwide.", region:"Americas", tags:["stonewall","lgbtq","rights","new york"] },
{ id:245, title:"Same-Sex Marriage Legalised — USA", year:2015, lat:38.9, lng:-77.04, category:"politics", impact:"HIGH", description:"The US Supreme Court ruled in Obergefell v. Hodges that same-sex couples have a constitutional right to marry in all 50 states — a landmark ruling in the decades-long struggle for LGBTQ equality.", region:"Americas", tags:["same-sex marriage","lgbtq","supreme court","usa"] },
{ id:246, title:"Me Too Movement Goes Global", year:2017, lat:34.05, lng:-118.24, category:"culture", impact:"HIGH", description:"The #MeToo movement, reignited by exposés of Harvey Weinstein, spread globally as millions shared experiences of sexual harassment and assault, triggering widespread cultural and institutional reckoning.", region:"Americas", tags:["me too","harassment","women's rights","movement"] },
{ id:247, title:"Nelson Mandela Released from Prison", year:1990, lat:-33.92, lng:18.42, category:"politics", impact:"HIGH", description:"Nelson Mandela walked free from Victor Verster Prison after 27 years. His release made him the most celebrated political prisoner in history and began the process of dismantling South Africa's apartheid system.", region:"Africa", tags:["mandela","prison","apartheid","south africa"] },
{ id:248, title:"Camp David Accords — Egypt-Israel Peace", year:1978, lat:39.65, lng:-77.47, category:"politics", impact:"HIGH", description:"US President Carter brokered a peace agreement between Egyptian President Sadat and Israeli PM Begin at Camp David — the first peace treaty between Israel and an Arab nation and a landmark of Middle East diplomacy.", region:"Americas", tags:["camp david","egypt","israel","peace","carter"] },
{ id:249, title:"Oslo Accords — Israeli-Palestinian Recognition", year:1993, lat:31.77, lng:35.23, category:"politics", impact:"HIGH", description:"The Oslo Accords established limited Palestinian self-governance and Israeli-Palestinian mutual recognition, raising hopes for a two-state solution. The process ultimately failed but remains the framework for negotiations.", region:"Middle East", tags:["oslo","palestine","israel","peace"] },
{ id:250, title:"South Korea Democratises", year:1987, lat:37.57, lng:126.98, category:"politics", impact:"MEDIUM", description:"Massive pro-democracy protests forced South Korea's military government to agree to direct presidential elections. South Korea's democratic transition became a model for how authoritarian regimes can peacefully democratise.", region:"Asia", tags:["south korea","democracy","protest","elections"] },

// ══════════════════════════════════════
// FINAL BATCH — VARIETY
// ══════════════════════════════════════
{ id:251, title:"Panama Canal Completed", year:1914, lat:9.08, lng:-79.68, category:"economy", impact:"HIGH", description:"The 77km Panama Canal connecting the Atlantic and Pacific Oceans was completed, halving voyage times between the oceans and transforming global maritime trade.", region:"Americas", tags:["panama canal","engineering","trade","usa"] },
{ id:252, title:"Suez Crisis — End of British Imperial Power", year:1956, lat:30.43, lng:32.34, category:"war", impact:"HIGH", description:"Egypt nationalised the Suez Canal; Britain, France, and Israel invaded. US pressure forced a humiliating withdrawal, demonstrating the end of European imperial power and the rise of the Cold War superpowers.", region:"Middle East", tags:["suez","egypt","nasser","britain"] },
{ id:253, title:"Cuban Revolution — Castro Takes Power", year:1959, lat:23.11, lng:-82.37, category:"politics", impact:"HIGH", description:"Fidel Castro's revolutionary forces overthrew the US-backed Batista regime, establishing a communist government 90 miles from Florida and becoming a major Cold War flashpoint.", region:"Americas", tags:["cuba","castro","revolution","communism"] },
{ id:254, title:"Berlin Wall Built — Germany Divided", year:1961, lat:52.52, lng:13.41, category:"politics", impact:"HIGH", description:"East Germany built a wall dividing Berlin overnight, sealing the border that 3.5 million East Germans had used to flee. The Wall became the defining symbol of the Iron Curtain.", region:"Europe", tags:["berlin wall","cold war","germany","iron curtain"] },
{ id:255, title:"Martin Luther King Jr. Assassinated", year:1968, lat:35.14, lng:-90.05, category:"politics", impact:"HIGH", description:"Dr. Martin Luther King Jr. was shot and killed on the balcony of the Lorraine Motel in Memphis, triggering riots in over 100 US cities. He had just expanded his movement to address economic inequality.", region:"Americas", tags:["martin luther king","assassination","civil rights"] },
{ id:256, title:"Six-Day War — Israel Captures Jerusalem", year:1967, lat:31.77, lng:35.23, category:"war", impact:"HIGH", description:"Israel's pre-emptive strikes destroyed Arab air forces in hours, and in six days Israel captured the West Bank, Gaza, Sinai, and the Golan Heights — territories central to all subsequent Middle East negotiations.", region:"Middle East", tags:["six day war","israel","egypt","jerusalem"] },
{ id:257, title:"Iran-Iraq War", year:1980, lat:33.34, lng:44.4, category:"war", impact:"HIGH", description:"Iraq invaded Iran, beginning an eight-year war that killed over 500,000 people and used chemical weapons. It left both nations economically devastated and reshaped Middle Eastern geopolitics.", region:"Middle East", tags:["iran","iraq","war","chemical weapons"] },
{ id:258, title:"Deepwater Horizon Oil Spill", year:2010, lat:28.74, lng:-88.39, category:"disaster", impact:"HIGH", description:"The BP rig explosion released 4.9 million barrels of oil into the Gulf of Mexico over 87 days — the largest marine oil spill in history and a catastrophe for Gulf Coast ecosystems.", region:"Americas", tags:["deepwater horizon","oil","gulf","disaster"] },
{ id:259, title:"Arab Spring — Egypt's Tahrir Square Revolution", year:2011, lat:30.04, lng:31.24, category:"politics", impact:"HIGH", description:"Massive protests in Cairo's Tahrir Square forced the resignation of President Hosni Mubarak after 30 years in power, inspiring millions across the Middle East and demonstrating social media's political power.", region:"Africa", tags:["egypt","tahrir","mubarak","arab spring"] },
{ id:260, title:"Death of Bin Laden — Navy SEAL Operation", year:2011, lat:34.16, lng:73.22, category:"war", impact:"HIGH", description:"US Navy SEALs killed Osama bin Laden in a compound in Abbottabad, Pakistan, nearly ten years after the 9/11 attacks. The operation removed the world's most wanted terrorist.", region:"Asia", tags:["bin laden","usa","al-qaeda","seal team 6"] },
{ id:261, title:"Crimean War — Florence Nightingale's Revolution", year:1853, lat:44.95, lng:34.1, category:"war", impact:"HIGH", description:"The Crimean War saw Britain, France, and Turkey fighting Russia. Florence Nightingale's work in field hospitals launched modern nursing. The conflict exposed military weaknesses in all major powers.", region:"Europe", tags:["crimean war","russia","nightingale","nursing"] },
{ id:262, title:"Battle of Verdun — Meat Grinder of WWI", year:1916, lat:49.16, lng:5.38, category:"war", impact:"HIGH", description:"The Battle of Verdun lasted 10 months and caused approximately 700,000 casualties in a few square kilometres of French countryside, exemplifying the industrial slaughter of WWI trench warfare.", region:"Europe", tags:["verdun","wwi","france","germany"] },
{ id:263, title:"Nanking Massacre", year:1937, lat:32.06, lng:118.8, category:"war", impact:"HIGH", description:"Japanese forces systematically massacred between 40,000 and 300,000 Chinese civilians and POWs in Nanking over six weeks. The atrocity remains one of the most controversial events in Sino-Japanese history.", region:"Asia", tags:["nanking","japan","china","massacre"] },
{ id:264, title:"Kristallnacht — Night of Broken Glass", year:1938, lat:52.52, lng:13.41, category:"war", impact:"HIGH", description:"Coordinated Nazi attacks destroyed 7,500 Jewish businesses, burned 1,400 synagogues, and killed at least 100 Jews. The pogrom marked the acceleration of the Nazi campaign to eliminate Jewish people.", region:"Europe", tags:["kristallnacht","nazi","antisemitism","germany"] },
{ id:265, title:"Liberation of Paris", year:1944, lat:48.85, lng:2.35, category:"war", impact:"HIGH", description:"Free French forces entered Paris on August 25, ending four years of Nazi occupation. General de Gaulle led a triumphant march down the Champs-Élysées amid scenes of delirious celebration.", region:"Europe", tags:["paris","liberation","wwii","de gaulle"] },
{ id:266, title:"Nuremberg Trials — War Crimes Accountability", year:1945, lat:49.45, lng:11.07, category:"politics", impact:"HIGH", description:"The International Military Tribunal tried 24 leading Nazis for war crimes and crimes against humanity, establishing the precedent of individual criminal responsibility for state-sponsored atrocities.", region:"Europe", tags:["nuremberg","war crimes","nazi","international law"] },
{ id:267, title:"Berlin Blockade and Airlift", year:1948, lat:52.52, lng:13.41, category:"war", impact:"HIGH", description:"The Soviet Union blockaded West Berlin; the Western Allies responded with an 11-month airlift. The successful operation demonstrated Western resolve and was a defining moment of the early Cold War.", region:"Europe", tags:["berlin","airlift","cold war","soviet"] },
{ id:268, title:"Independence of African Nations — 1960", year:1960, lat:0.0, lng:20.0, category:"politics", impact:"HIGH", description:"1960 saw 17 African nations gain independence from European colonial powers in a single year — dubbed the 'Year of Africa'. Harold Macmillan's 'wind of change' speech acknowledged the irreversible force of African nationalism.", region:"Africa", tags:["africa","independence","decolonisation","1960"] },
{ id:269, title:"Cultural Revolution in China", year:1966, lat:39.9, lng:116.4, category:"politics", impact:"HIGH", description:"Mao Zedong launched the Cultural Revolution, unleashing Red Guards to destroy the 'Four Olds'. An estimated 500,000–2 million people died and countless cultural treasures were destroyed.", region:"Asia", tags:["cultural revolution","mao","china","red guards"] },
{ id:270, title:"Tet Offensive — Vietnam War Turning Point", year:1968, lat:16.05, lng:108.2, category:"war", impact:"HIGH", description:"North Vietnamese forces launched massive coordinated surprise attacks during the Tet holiday, shocking Americans who had been told the war was being won. It was a turning point in public opinion against the war.", region:"Asia", tags:["vietnam","tet offensive","usa","war"] },

]; // end HISTORICAL_EVENTS

